7fc450fb0b2cd4e9abe5f487fcc0403c53af69bbb48e9afabb41f4aa80f68de8 {"key": "7fc450fb0b2cd4e9abe5f487fcc0403c53af69bbb48e9afabb41f4aa80f68de8", "original": {"closure_evidence": [], "counterexample": "基线激活目标为合法激活后 A；Rollback 预检通过后，OnPredict 一次性替换成 X/candidate-ready；预测端口读 X 并接受 alreadyTarget，事务持久化 Hash(X)，Undo 因状态已是 before 跳过写入，写集同步至 X，随后快照恢复覆盖 X 并可能报告回滚成功。", "id": "R5-MUST-2", "obligation": "implementation", "paths": ["MultiplayerHoeingAssistant/Services/TaskCenter/MigrationSwitchTransaction.cs", "MultiplayerHoeingAssistant/Services/TaskCenter/MigrationReferenceActivation.cs", "Test/MultiplayerHoeingAssistant.UnitTest/ServiceTests/TaskCenter/R56ReferenceActivationWiringTests.cs"], "repair_steps": ["在真实预测端口读取到用于转换的同一字节数组后验证其SHA-256等于事务传入的已确认expectedInputHash；不符时不产出预测值、不持久化RevertedHash。", "保留事务端写集预检但不能把它当成端口内版本绑定的替代。", "检查Undo实际写口也只在请求期望版本匹配时写入；任意外来X漂移须拒绝并保留。"], "root_cause": "第六轮原文：预测前的写集哈希检查与预测端口实际读盘没有绑定；端口没有校验事务提供的预期输入版本，故未经确认内容可能成为 RevertedHash 并让回滚覆盖他方数据。当前 expectedInputHash 为候选修复，尚未按新流程独立闭环。", "severity": "must", "status": "open", "tests": ["PredictRejectsDriftBetweenPrecheckAndPortRead", "OneShotDisturbanceAfterPrecheck_IsRejectedByVersionBinding", "对expectedInputHash比较做反向突变，具名断言须失败并绑定最终源码SHA。"]}, "source": "_workflow/r56-reference-activation-wiring-2026-09-29/review-process/registration.json"}
84637bd1c030bcf32e3c8cd51bcc8863d2920780349d8a92209962060afe6ee9 {"key": "84637bd1c030bcf32e3c8cd51bcc8863d2920780349d8a92209962060afe6ee9", "original": {"closure_evidence": [], "counterexample": "原round1 MUST-1：确认引用B后改成X，激活把X登记合法。其延续round2 MUST-3、round3 MUST-3分别指出端口读取未绑定和调用方可提供X哈希。当前代码静态补齐这些检查，但没有认证最终执行。", "id": "R1-MUST-1", "obligation": "implementation", "paths": ["_workflow/r56-reference-activation-wiring-2026-09-29/consultation/review-round1-report.raw.md", "_workflow/r56-reference-activation-wiring-2026-09-29/consultation/review-round2-report.raw.md", "_workflow/r56-reference-activation-wiring-2026-09-29/consultation/review-round3-report.raw.md", "MultiplayerHoeingAssistant/Services/TaskCenter/MigrationSwitchTransaction.cs", "MultiplayerHoeingAssistant/Services/TaskCenter/MigrationReferenceActivation.cs", "Test/MultiplayerHoeingAssistant.UnitTest/ServiceTests/TaskCenter/R56ReferenceActivationWiringTests.cs"], "repair_steps": "保留ActivateCandidate的confirmedHash检查、错误调用方哈希拒绝和事务构造请求，以及真实Activate对输入字节的核验；修复读回版本吸收后，以最终源码重新认证原反例。此ID为round1原条目索引，round2/3延续等级和含义均保留。", "root_cause": "激活输入版本与确认写集的绑定曾不完整；后续静态修复结论不是执行闭环。", "severity": "must", "status": "open", "tests": "Activation_AfterDrift_IsNotAbsorbed、ActivationRejectsCallerSuppliedForeignHash、一次性Activation_VersionBinding反例；分别削弱事务请求绑定和端口绑定，证明错误激活及证据吸收被具名断言检出。"}, "source": "_workflow/r56-reference-activation-wiring-2026-09-29/review-process/requests/001/report.json"}
85f5e15229d10ff9bf90d963a6fefd5bdce67205b055333525d270c7edef31d0 {"key": "85f5e15229d10ff9bf90d963a6fefd5bdce67205b055333525d270c7edef31d0", "original": {"closure_evidence": [], "counterexample": "一个合法 schema1 SnapshotReady manifest，或无 ActivationRecord 的旧 Mark* 演练 manifest，在两个已知摘要算法下均得到相同合法摘要。按 PLAN-v1 的字面规则，它同时匹配两种格式而被拒绝；这与同段要求兼容“无 activation”固定 fixtures，以及 source-matrix 的合法旧标记夹具转换承诺冲突。", "id": "PLAN-COMPATIBILITY-1", "obligation": "plan", "paths": ["_workflow/r56-reference-activation-wiring-2026-09-29/native-recovery-20261001/PLAN-v1.md:69", "_workflow/r56-reference-activation-wiring-2026-09-29/native-recovery-20261001/source-matrix.md:124", "MultiplayerHoeingAssistant/Services/TaskCenter/MigrationSwitchTransaction.cs:1381", "MultiplayerHoeingAssistant/Services/TaskCenter/MigrationSwitchTransaction.cs:1404", "Test/MultiplayerHoeingAssistant.UnitTest/ServiceTests/TaskCenter/R56MigrationSwitchTransactionTests.cs"], "repair_steps": ["按已知格式的字段集合、原结构关系和原摘要算法识别语义验证类。多种算法若在该记录上产生完全相同的验证语义与转换结果，应视为一个等价类；只有结果或授权语义冲突才属于拒绝的歧义。", "固定 pre-revertedHash 和含 revertedHash 两种格式的字段政策；旧算法不得忽略新增的授权字段后仍将它们作为事实转换。", "转换记录保留原始字节、SHA 与匹配的等价格式来源；先验证后转换，不重签非法旧记录。", "将无激活记录、带激活记录、回滚中间态、篡改和转换中断的预期结果写成明确兼容表。"], "root_cause": "旧格式识别规则“唯一匹配一个已知格式，歧义拒绝”把算法标签唯一性当成合法记录唯一性。冻结 diff 证明 pre-revertedHash 与当前算法仅在非空 ActivationRecord 分支的摘要材料不同；无激活记录时两者摘要完全相同。", "severity": "important", "status": "open", "tests": ["LegacyManifestWithoutActivation_MatchesEquivalentFormatsAndUpgrades：固定历史原始字节；两个算法命中但转换成功且无真实权限增加。", "LegacyActivatedManifest_ValidatedBeforeUpgrade。", "LegacyCommittedManifest_RetainsVerifiedEvidence。", "LegacyPreRevertedFormatWithInjectedRevertedHash_IsRejected：旧摘要不变也不能提升未经签入的字段。", "LegacyManifestTamper_IsRejectedWithoutResigning。", "ManifestUpgradeInterrupted_ReopenUsesCompleteVersion。", "分别突变为按命中算法数量拒绝、忽略旧字段关系、直接当前重签；各有独立行为断言及 P/F/P。"]}, "source": "_workflow/r56-reference-activation-wiring-2026-09-29/native-recovery-20261001/native/requests/ad38c19cd8c347cfa461de14e7961fed/report.json"}
