aac835db1fffa29e1b7db3bc3ffc9098fb810025775831befb129078e238460a {"key": "aac835db1fffa29e1b7db3bc3ffc9098fb810025775831befb129078e238460a", "original": {"closure_evidence": [], "counterexample": "lazy enumerable先同线程重入RecordChanges成功登记第二项，再yield外层项；外层旧局部m可以覆盖内层成功登记。该枚举站SuppressFlow worker mutation并等待，可形成monitor等待死锁。显式stageHook和prepared seam夹具未覆盖此站。未执行实验。", "id": "R5-IMPORTANT-3", "obligation": "implementation", "paths": ["MultiplayerHoeingAssistant/Services/TaskCenter/MigrationSwitchTransaction.cs:559", "MultiplayerHoeingAssistant/Services/TaskCenter/MigrationSwitchTransaction.cs:570", "MultiplayerHoeingAssistant/Services/TaskCenter/MigrationSwitchTransaction.cs:623", "MultiplayerHoeingAssistant/Services/TaskCenter/MigrationSwitchTransaction.cs:2992"], "repair_steps": ["在明确回调guard内消费并克隆调用方集合/记录，随后仅验证和使用本地快照。", "同步处理ReferencePlan.Targets的Count/枚举/索引消费，不在guard外再次调用用户集合代码。", "冻结后核对原main输入和资格；正常无回调并发仍串行，Dispose仍延后到最外层结束。"], "root_cause": "调用方IEnumerable的GetEnumerator/MoveNext在持有monitor并取得局部manifest后被直接消费，未进入callback guard或不可变输入冻结。", "severity": "important", "status": "open", "tests": ["lazy输入同步重入、无流worker等待及自定义ReferencePlan集合冻结反例。", "断言重入拒绝、登记未丢失、bounded completion和外层状态正确。", "撤回输入guard/冻结做单点行为P/F/P；普通数组/列表及并发串行对照保持绿色。"]}, "source": "_workflow/r56-reference-activation-wiring-2026-09-29/native-recovery-20261001/native-compatibility-v9/requests/911b636e813d4487ba4c9bdfb791070c/report.json"}
abf399beddfbdb4ca637d998c6fadff42c081140eea37e7b9ab2b0d4726b4560 {"key": "abf399beddfbdb4ca637d998c6fadff42c081140eea37e7b9ab2b0d4726b4560", "original": {"closure_evidence": [], "counterexample": "正常candidate-ready流程已经完成标准配置安装，ApplyReferenceUpdate已提交含nativeMigrationTransactionId的流程字节；在ActivateCandidate、RehearseRollback或Commit前后发生异常/进程退出。重开后LoadSnapshot拒绝未Committed流程。用户按错误提示点击“迁移回退”，Host在297行再次LoadSnapshot并被拒，未到达305行真实事务回退，也未到达309行原BGI标准配置回退。原文件和事务尚在，仍无受支持的恢复入口。这是当前源码静态可达反例，本审未执行。", "id": "MIGRATION-RECOVERY-ENTRY-1", "obligation": "implementation", "paths": ["MultiplayerHoeingAssistant/Services/TaskCenter/WorkflowMigrationConsumer.cs:39", "MultiplayerHoeingAssistant/Services/TaskCenter/WorkflowMigrationConsumer.cs:48", "MultiplayerHoeingAssistant/Services/TaskCenter/WorkflowStore.cs:147", "MultiplayerHoeingAssistant/Services/TaskCenter/WorkflowStore.cs:154", "MultiplayerHoeingAssistant/Services/TaskCenter/TaskCenterHost.cs:297", "MultiplayerHoeingAssistant/Services/TaskCenter/TaskCenterHost.cs:302", "MultiplayerHoeingAssistant/Services/TaskCenter/TaskCenterHost.cs:305", "MultiplayerHoeingAssistant/ViewModels/TaskCenterPanelViewModel.cs:81", "MultiplayerHoeingAssistant/Views/MistletoePage.xaml:1731", "Test/MultiplayerHoeingAssistant.UnitTest/ServiceTests/TaskCenter/WorkflowMigrationConsumerTests.cs:26", "Test/MultiplayerHoeingAssistant.UnitTest/ServiceTests/TaskCenter/WorkflowMigrationConsumerTests.cs:71"], "release_classification": "本版直接阻断正常迁移的中断恢复与整体回退；局部阻断关联迁移路径", "repair_steps": ["保持LoadSnapshot的未提交拒绝：执行、启动、编辑、分享及普通加载不得借恢复入口取得可执行文档。", "为回退建立狭窄的恢复元数据读取合同，或先由既有事务/持久来源索引取得恢复身份。返回恢复描述，不返回可供Runner使用的执行快照。", "恢复读取核对请求workflowId、文件路径、原事务ID、manifest完整性、ConfigRoot、已声明目标/ActivationRecord路径及持久操作链。允许已有合法中间阶段进入既有Rollback；不猜测、重建或替换缺失/损坏的事务身份。", "沿原source-index和installation binding确定标准配置安装身份，先验证原BGI User根和安装记录；换根、陌生事务、来源歧义、目标后改均拒绝并保留原件。", "回退继续由既有MigrationSwitchTransaction和StandardMigrationConsumer执行。流程回退与BGI回退分别读回；第二端未确认时报告整体回退未完成，不能Effective。", "页面只为具有可验证恢复身份的条目开放恢复命令。不要通过取消所有IsQuarantined守卫开放任意隔离文件写入；无法核验者显示具体阻断。", "按原包集中修复这一入口及必要测试；不重开Goal、opening或审查额度，不改本固定报告结论。"], "root_cause": "WorkflowMigrationConsumer.Activate先把nativeMigrationTransactionId写入流程，再依次激活、演练、Commit。WorkflowStore.LoadSnapshot要求携带该字段的流程已经Committed，正确阻止未提交候选执行和编辑。但TaskCenterHost.RollbackMigrationAsync在调用真实WorkflowMigrationConsumer.Rollback之前也先调用同一LoadSnapshot。因而引用更新已实际发布、后续提交尚未完成的合法事务，进入回退会先得到“迁移提交未确认”的隔离异常。界面使用原Host入口，没有独立、仅供恢复的身份读取合同。", "severity": "important", "status": "open", "tests": ["红反例：真实引用事务已经写入nativeMigrationTransactionId但尚未Committed，原Host回退失败；断言未提交文件仍不能启动/编辑。", "引用更新后、激活前中断：新Host从原入口回退，流程及标准配置恢复原字节，原事务身份不变。", "激活后、演练或Commit失败：同一原入口可恢复；重复回退幂等；没有新事务或重复安装。", "带损坏/陌生事务ID、错误ConfigRoot、错误目标路径的恢复请求零写入并保留原件。", "原BGI根变更或安装绑定缺失：拒绝整体回退成功，原两个根保全；回到原根可继续。", "页面真实命令能到达合法恢复入口；执行/编辑读取仍拒绝未提交候选。", "关键反向突变：恢复入口重新使用执行LoadSnapshot时，合法中断回退行为断言变红；放宽事务/目标根身份守卫时，陌生事务或换根零写入断言变红；finally恢复并读回源码SHA。", "修复后Rebuild及迁移、标准安装、WorkflowStore、Host管理受影响回归；新产物与验证清单身份重新绑定。"]}, "source": "_workflow/local-wait-admission-gates-20261004/auto-relay-management-migration-20261005-from-01a10954/auto-standard-install-01a10c1c/01a10c87-deee-7381-a61d-fefce264d537/comprehensive-review-2-report.json"}
ac5d492f1a9c9c04c963a85d629c1be1dd098f62cd99467577774e3dfe434fe7 {"key": "ac5d492f1a9c9c04c963a85d629c1be1dd098f62cd99467577774e3dfe434fe7", "original": {"closure_evidence": [], "counterexample": "变更前schemaVersion=1的合法Activated/Committed manifest带ActivationRecord且摘要不包含revertedHash；当前仍要求schemaVersion=1，但ComputeManifestIntegrity追加:<null>，LoadValidated拒绝旧记录，RecoverOnStart无法处理。", "id": "IMPLEMENTATION-MANIFEST-COMPATIBILITY-1", "obligation": "implementation", "paths": ["__review__/git.json", "MultiplayerHoeingAssistant/Services/TaskCenter/MigrationSwitchTransaction.cs", "Test/MultiplayerHoeingAssistant.UnitTest/ServiceTests/TaskCenter/R56MigrationSwitchTransactionTests.cs"], "repair_steps": "按批准的版本兼容方案实现旧格式摘要验证和受锁转换，显式标识新格式；新增意图字段同样使用版本化摘要。先验证旧记录原摘要和关系，再转换，绝不对不可信旧记录直接重新签摘要。", "root_cause": "持久化完整性格式发生变化，但运行manifest版本和旧格式验证没有对应变化。", "severity": "important", "status": "open", "tests": "真实变更前manifest固定字节兼容测试，覆盖带ActivationRecord和无ActivationRecord、各恢复阶段、篡改拒绝及转换中断重开；新旧Mark*夹具回归。"}, "source": "_workflow/r56-reference-activation-wiring-2026-09-29/review-process/requests/001/report.json"}
