85:        if(c.Kind=="weekdays") return WorkflowWeekdayFilter.Matches(new WorkflowStrategy{Kind="condition.weekdays",Params=new(){["days"]=JsonSerializer.SerializeToElement(c.Days)}},now);
86:        var from=TimeOnly.ParseExact(c.From!,"HH:mm");var until=TimeOnly.ParseExact(c.Until!,"HH:mm");var time=TimeOnly.FromDateTime(now.DateTime);
87:        return from<=until ? time>=from && time<until : time>=from || time<until;
88:    }
89:
90:    private WorkflowNodeOccurrence? PathSuccessor(WorkflowNodeOccurrence current,string? result)
91:    {
92:        var n=NodeAt(current);
93:        if(n.Kind=="control.end") return null;
94:        var target=n.Kind=="control.condition"
95:            ? result switch {"branchYes"=>n.Path?.Yes,"branchNo"=>n.Path?.No,"skippedUser" or "skippedFilter"=>n.Path?.Next ?? "$end",_=>throw new InvalidOperationException("判断结果尚未持久化，禁止猜测去向")}
96:            : n.Path?.Next;
97:        if(target=="$end") return _doc.Loop is null ? null : OccurrenceAt(0,checked(current.LoopIteration+1));
98:        var outputLane=current.PathLane ?? Lane(n);
99:        int index;
100:        if(target is not null && LaneTarget(target,out var targetLane,out var targetTime))
101:        {
102:            outputLane=targetLane;
103:            index=_doc.Nodes.FindIndex(x=>Covers(x,targetLane)
104:                && (targetTime is {} at ? TimeOnly.TryParseExact(x.Strategies.LastOrDefault(s=>s.Kind=="schedule.time")?.GetString("time"),"HH:mm",out var time) && time>=at : _doc.Nodes.IndexOf(x)>current.SequenceIndex));
105:            if(index<0)return null;
106:        }
107:        else if(target is null)
108:        {
109:            index=_doc.Nodes.FindIndex(current.SequenceIndex+1,x=>Covers(x,outputLane));
110:            if(index<0)index=_doc.Nodes.Count;
111:        }
112:        else
113:        {
114:            index=_doc.Nodes.FindIndex(x=>x.NodeId==target);
115:            if(index>=0 && !Covers(_doc.Nodes[index],outputLane))outputLane=Lane(_doc.Nodes[index]);
116:        }
117:        if(index<0) throw new InvalidOperationException("流程去向已失效，禁止降级顺序执行");
118:        if(index>=_doc.Nodes.Count) return _doc.Loop is null ? null : OccurrenceAt(0,checked(current.LoopIteration+1));
119:        // 回边产生新的路径轮次，前向同轮不重复。与旧提交/前置/停驻身份同构，恢复仍用已落盘轮次。
120:        return OccurrenceAt(index,index<=current.SequenceIndex ? checked(current.LoopIteration+1) : current.LoopIteration) with {PathLane=outputLane};
121:    }
122:}
