6:/// <summary>Node time is anchored to the durable run day, so resuming cannot silently move it to tomorrow.</summary>
7:public static class WorkflowNodeSchedule
8:{
9:    internal static string TimingKey(string nodeId, int occurrence, int loopIteration)
10:        => $"nodeTiming:schedule.time:{nodeId}:{occurrence}:{loopIteration}";
11:
12:    internal static WorkflowTriggerTiming? Read(WorkflowRunRecord run, string nodeId, int occurrence, int loopIteration)
13:    {
14:        if (run.ExtensionData?.TryGetValue(TimingKey(nodeId, occurrence, loopIteration), out var saved) == true)
15:            return saved.Deserialize<WorkflowTriggerTiming>() ?? throw new InvalidOperationException("节点排程持久时刻不可读取");
16:        // 旧候选的键不含出现序号，只能在无歧义的首次出现复用。
17:        if (occurrence == 0 && run.ExtensionData?.TryGetValue($"nodeTiming:schedule.time:{nodeId}:{loopIteration}", out saved) == true)
18:            return saved.Deserialize<WorkflowTriggerTiming>() ?? throw new InvalidOperationException("旧节点排程持久时刻不可读取");
19:        return null;
20:    }
21:
22:    internal static WorkflowTriggerTiming? Effective(WorkflowRunRecord run, WorkflowNode node, WorkflowNodeOccurrence occurrence)
23:    {
24:        var schedule = node.Strategies.LastOrDefault(s => s.Kind == "schedule.time");
25:        if (schedule is null) return run.TriggerTiming;
26:        var timing = Read(run, occurrence.NodeId, occurrence.Occurrence, occurrence.LoopIteration)
27:            ?? throw new InvalidOperationException("本次节点尚未绑定持久排程时刻，禁止自报排序");
28:        var expected = Resolve(schedule, timing.ScheduledAt, out var error)
29:            ?? throw new InvalidOperationException(error);
30:        if (expected.Kind != timing.Kind || expected.ScheduledAt != timing.ScheduledAt || expected.WindowEndsAt != timing.WindowEndsAt)
31:            throw new InvalidOperationException("节点排程与本次定义不匹配，保留原时刻并禁止提交");
32:        return timing;
33:    }
34:
35:    internal static WorkflowTriggerTiming Bind(WorkflowRunRecord run, WorkflowNode node, WorkflowNodeOccurrence occurrence, DateTimeOffset now)
36:    {
37:        if (Read(run, occurrence.NodeId, occurrence.Occurrence, occurrence.LoopIteration) is not null)
38:            return Effective(run, node, occurrence)!;
39:        var schedule = node.Strategies.Last(s => s.Kind == "schedule.time");
40:        var previous = run.NodeOutcomes.AsEnumerable().Reverse()
41:            .Select(o => Read(run, o.NodeId, o.Occurrence, o.LoopIteration)).FirstOrDefault(t => t is not null);
42:        var prior = run.NodeOutcomes.AsEnumerable().Reverse().Where(o=>o.NodeId==occurrence.NodeId && o.Occurrence==occurrence.Occurrence)
43:            .Select(o=>Read(run,o.NodeId,o.Occurrence,o.LoopIteration)).FirstOrDefault(t=>t is not null);
44:        var repeated = prior is not null;
45:        var day = previous?.ScheduledAt ?? run.TriggerTiming?.ScheduledAt ?? run.CreatedAt;
46:        if(repeated && schedule.GetString("mode")=="sequence")
47:        {
48:            // 顺序型是本轮开始下限；合法再次到达不附加“每日一次”门槛。
49:            day=prior!.ScheduledAt;
50:            if(run.ExtensionData?.TryGetValue("loopRoundStart:"+occurrence.LoopIteration,out var roundStart)==true)
51:                day=roundStart.Deserialize<DateTimeOffset>();
52:        }
53:        var timing = Resolve(schedule, day, out var error) ?? throw new InvalidOperationException(error);
54:        // 首次到达的前向跨午夜沿路径选日；重复在原下限/有效窗口内继续执行。冷恢复只读既存值。
55:        if (!repeated && previous is not null && timing.ScheduledAt < previous.ScheduledAt)
56:            timing = ShiftDay(timing);
57:        if (occurrence.LoopIteration > 0 && timing.Kind != "trigger.time")
58:        {
59:            while (timing.Kind=="trigger.timeFixed" ? now>=timing.ScheduledAt.AddMinutes(1) : now>=timing.WindowEndsAt)
60:                timing = ShiftDay(timing);
61:        }
62:        run.ExtensionData ??= new();
63:        run.ExtensionData[TimingKey(occurrence.NodeId, occurrence.Occurrence, occurrence.LoopIteration)] = JsonSerializer.SerializeToElement(timing);
64:        return timing;
65:    }
66:
67:    private static WorkflowTriggerTiming ShiftDay(WorkflowTriggerTiming timing)
68:        => timing with { ScheduledAt = timing.ScheduledAt.AddDays(1), WindowEndsAt = timing.WindowEndsAt?.AddDays(1) };
69:
70:    internal static bool FixedDeclared(WorkflowRunRecord run, DateTimeOffset now)
71:    {
72:        if (run.State != WorkflowRunState.Waiting) return false;
73:        var cursor = run.Cursor;
74:        var timing = cursor is null ? null : Read(run, cursor.NodeId, cursor.Occurrence, cursor.LoopIteration);
75:        timing ??= run.TriggerTiming;
76:        return timing is { Kind: "trigger.timeFixed" } && timing.ScheduledAt <= now && now < timing.ScheduledAt.AddMinutes(1);
77:    }
78:
79:    public static WorkflowTriggerTiming? Resolve(WorkflowStrategy schedule, DateTimeOffset runDay, out string? error)
80:    {
81:        error = null;
82:        var mode = schedule.GetString("mode");
83:        if (mode is not ("sequence" or "fixed" or "flexible")) { error = "节点执行方式无效"; return null; }
84:        if (!TimeOnly.TryParseExact(schedule.GetString("time"), "HH:mm", out var time)) { error = "节点时间须为HH:mm"; return null; }
85:        var at = new DateTimeOffset(runDay.Year, runDay.Month, runDay.Day, time.Hour, time.Minute, 0, runDay.Offset);
86:        DateTimeOffset? until = null;
87:        if (mode == "flexible")
88:        {
89:            if (!TimeOnly.TryParseExact(schedule.GetString("until"), "HH:mm", out var end)) { error = "节点窗口结束须为HH:mm"; return null; }
90:            until = new DateTimeOffset(at.Year, at.Month, at.Day, end.Hour, end.Minute, 0, at.Offset);
91:            if (until <= at) until = until.Value.AddDays(1);
92:        }
93:        return new WorkflowTriggerTiming(mode == "flexible" ? "trigger.timeFlexible" : mode == "fixed" ? "trigger.timeFixed" : "trigger.time", at, until) { MissPolicy = "skip" };
94:    }
95:}
