362:    public void RequestAction(string runId, WorkflowRunAction action)
363:    {
364:        if (!_controls.TryGetValue(runId, out var control)) return;
365:        control.Actions.Enqueue(action);
366:        switch (action)
367:        {
368:            case WorkflowRunAction.Stop:
369:                try
370:                {
371:                    if (!_runs.UpdateMergingIf(runId, latest =>
372:                        {
373:                            if (!string.Equals(latest.RunId, runId, StringComparison.Ordinal)) return false;
374:                            latest.StopRequested = true;
375:                            return true;
376:                        }, out _))
377:                        throw new InvalidOperationException("停止意图未能耐久登记，未确认停止完成。");
378:                }
379:                finally { control.RunCts.Cancel(); }
380:                break;
381:            case WorkflowRunAction.Pause:
382:                control.PauseRequested = true;
383:                control.PauseSignal.TrySetResult();
384:                break;
385:            case WorkflowRunAction.SkipCurrent:
386:            {
387:                // B4：绑定请求时的当前游标身份；等待期间无执行中节点，不登记（等待可经 Stop 中断）
