500:    /// 仅接受 Interrupted/Paused；Unknown 拒绝自动恢复（结果不确定，需先按幂等键+job 查询对账）。
501:    /// 恢复点 = 游标身份在当前修订中重定位；已完成节点不重放；历史失败结果参与聚合。
502:    /// </summary>
503:    public async Task<WorkflowRunRecord> ResumeAsync(string runId, CancellationToken ct = default)
504:    {
505:        var control = new RunControl { RunCts = CancellationTokenSource.CreateLinkedTokenSource(ct) };
506:        if (!_controls.TryAdd(runId, control))
507:        {
508:            control.RunCts.Dispose();
509:            throw new InvalidOperationException("运行登记冲突：" + runId);
510:        }
511:        try
512:        {
513:            // 先取得本 Runner 的运行控制，再读取与修改记录；控制冲突不得先写 Running/修订。
514:            var run = _runs.Load(runId) ?? throw new FileNotFoundException("运行记录不存在：" + runId);
515:            if (run.State == WorkflowRunState.Unknown)
516:                throw new InvalidOperationException("运行结果不确定（Unknown），需先按幂等键+job 查询对账，禁止自动恢复。");
517:            if (run.State is not (WorkflowRunState.Interrupted or WorkflowRunState.Paused
518:                or WorkflowRunState.LocalWaitParking))
519:                throw new InvalidOperationException($"仅 Interrupted/Paused/LocalWaitParking 可显式恢复（当前 {run.State}）。"
520:                    + "LocalWaitParking＝等待停驻（[批次 20／Wave3／C11=(a)]）：等待项就绪后显式重驱入口。");
521:            if (RunStore.HasUnresolvedExternalFact(run))
522:            {
523:                run.State = WorkflowRunState.Unknown;
524:                run.Note = AppendNote(run.Note, "显式恢复发现未决发送/收尾事实，标 Unknown，必须先对账，禁止重驱。");
525:                _runs.Update(run);
526:                throw new InvalidOperationException("运行记录含未决发送/收尾事实，已保留事实并标 Unknown；必须先对账，禁止自动恢复。");
527:            }
528:
529:            var snapshot = _workflows.LoadSnapshot(run.WorkflowId);
530:            var plan = new WorkflowPlan(snapshot.Document);
531:            var preflight = plan.Preflight(_boundary.SingleNativeSupported, _prerequisites.SupportedKinds, _terminal.SupportedKinds,
532:                _boundary.SuppressConfigCompletionSupported); // R4.6 I1/B6：能力协商预检（含 suppress 能力）
533:            if (!preflight.Executable)
534:                throw new InvalidOperationException("流程预检未通过：" + string.Join("；", preflight.BlockingReasons));
535:
536:            plan.ValidatePathCursor(run); // 改状态/取消旧等待前核对原车道身份。
537:            if (run.LocalWaitDecision is { Kind: LocalWaitDecisionKind.Wait or LocalWaitDecisionKind.Hold } priorDecision
538:                && run.CurrentSubmission?.Intent == SubmitIntentState.LocalWaitDeferred
539:                && !(run.LoopDeadlineAt is { } waitDeadline && _opt.Clock() >= waitDeadline))
540:            {
541:                var sameRevision = string.Equals(run.WorkflowRevision, snapshot.Revision, StringComparison.Ordinal);
542:                WorkflowNodeOccurrence? waitOccurrence = null;
543:                var sameCursor = false;
544:                if (run.Cursor is { } savedCursor
545:                    && plan.TryLocate(savedCursor.NodeId, savedCursor.Occurrence, savedCursor.LoopIteration, out var located))
546:                {
547:                    waitOccurrence = located;
548:                    sameCursor = true;
549:                }
550:                if (sameRevision && sameCursor)
551:                {
552:                    var currentOccurrence = waitOccurrence!;
553:                    var resumeRequest = CreateWaitDecisionRequest(run, currentOccurrence, run.Cursor!.Attempt, plan.NodeAt(currentOccurrence));
554:                    var decision = DecideLocalWait(resumeRequest, currentOccurrence)
555:                        ?? new LocalWaitDecisionRecord
556:                        {
557:                            Kind = LocalWaitDecisionKind.ContinueAdmission,
558:                            Context = ContextFromRequest(resumeRequest),
559:                            Reason = "测试接缝恢复按显式请求重驱",
560:                        };
561:                    if (decision.Kind is LocalWaitDecisionKind.Wait or LocalWaitDecisionKind.Hold)
562:                    {
563:                        if (decision.Kind == LocalWaitDecisionKind.Wait)
564:                        {
565:                            var prepared = TryRegisterLocalWait(run, currentOccurrence, run.Cursor!.Attempt, decision);
566:                            if (prepared.Decision?.Binding is { } refreshedBinding)
567:                            {
568:                                if (priorDecision.Binding is { } priorBinding
569:                                    && !SameWaitBindingPayload(priorBinding, refreshedBinding))
570:                                {
571:                                    CancelPersistedLocalWait(priorBinding, "恢复复核发现等待绑定身份/载荷漂移");
572:                        run.LocalWaitDecision = SanitizeWaitDecision(decision with
573:                        {
574:                            Kind = LocalWaitDecisionKind.Hold,
575:                            Binding = null,
576:                            Reason = "恢复复核发现来源、候选或队列载荷已漂移；旧绑定已取消，不以新快照替换。",
577:                            NoSendConfirmed = true,
578:                        });
579:                                }
580:                                else
581:                                {
582:                                    // 已存在的绑定不可被当前快照替换（包含其来源、身份、scope 与登记载荷）。
583:                                    run.LocalWaitDecision = SanitizeWaitDecision(prepared.Decision with
584:                                        { Binding = priorDecision.Binding ?? refreshedBinding });
585:                                }
586:                            }
587:                            else
588:                            {
589:                                CancelPersistedLocalWait(priorDecision.Binding, "恢复复核无法重建可信等待绑定");
590:                                run.LocalWaitDecision = SanitizeWaitDecision(decision with
591:                                {
592:                                    Kind = LocalWaitDecisionKind.Hold,
593:                                    Binding = null,
594:                                    Reason = prepared.Reason,
595:                                    NoSendConfirmed = true,
596:                                });
597:                            }
598:                        }
599:                        else
600:                        {
601:                            CancelPersistedLocalWait(priorDecision.Binding, "等待复核转为 Hold");
602:                            run.LocalWaitDecision = SanitizeWaitDecision(decision with { Binding = null });
603:                        }
604:                        run.State = WorkflowRunState.LocalWaitParking;
605:                        run.Note = AppendNote(run.Note, "显式恢复复核仍需本地等待/保持，未启动驱动、未发送。"
606:                            + Sanitize(run.LocalWaitDecision.Reason));
607:                        _runs.Update(run);
608:                        PublishPersistedLocalWait(run);
609:                        return run;
610:                    }
611:                }
612:
613:                // 继续准入或身份/修订漂移：先墓碑化旧队列项，再清除活动绑定；若写入失败则维持原停驻。
614:                CancelPersistedLocalWait(priorDecision.Binding, sameRevision && sameCursor
615:                    ? "显式恢复重新进入完整准入" : "流程修订或游标身份已漂移");
616:                run.LocalWaitDecision = null;
617:            }
618:
619:            // BO-6/7: explicit resume is a rescue boundary even when the saved cursor still exists.
620:            // A prior revision stamp or a current cursor must not hide an earlier live parked
621:            // obligation; recompute the plan-order successor from completion + all park history.
622:            // A persisted tail flag with live parks stays fail-closed through final aggregation.
623:            if (!run.TailReached && run.NodeOutcomes.Any(o => o.Result == LocalWaitResultWord))
624:            {
625:                var resumeSuccessor = RecomputeSuccessor(run, plan);
626:                ApplyRelocation(run, resumeSuccessor);
627:                Log(run, "显式恢复复核当前计划中的停驻义务，按锚/停驻全序重算恢复点。");
628:            }
629:
630:            FreezeLegacyFixedTriggerPolicy(run, snapshot);
631:            run.WorkflowRevision = snapshot.Revision; // 恢复即对账到当前修订（节点边界语义）
632:            run.State = WorkflowRunState.Running;
633:            run.Note = AppendNote(run.Note, "显式恢复运行（游标身份重定位，不重放已完成节点）。");
634:            _runs.Update(run);
635:            return await DriveAsync(run, plan, control).ConfigureAwait(false);
636:        }
637:        finally
638:        {
639:            _controls.TryRemove(runId, out _);
640:            control.RunCts.Dispose();
641:        }
642:    }
643:
644:    private async Task<WorkflowRunRecord> DriveAsync(WorkflowRunRecord run, WorkflowPlan plan, RunControl control)
645:    {
646:        var ct = control.RunCts.Token;
647:        var flowFailure = false;
648:        // [BO-8 / R29 重要；继承缺陷] 推进段按**稳定出现身份**过滤已完成项：恢复点（显式恢复重算、
649:        // 修订热重载重算、或链尾重入的停驻）之后的线性推进不得二次提交已完成出现——修订重排把已
650:        // 完成节点挪到恢复点之后时，旧行为会重复触发外部副作用（不可撤销）。过滤只按
651:        // (NodeId, Occurrence, LoopIteration) 判定；停驻标记（LocalWaitResultWord）不算完成，
652:        // 停驻义务照常重驱。
653:        // [BO-9 / R34 F5 重要] 真实链尾仍存活的停驻义务按计划全序重入驱动（TryRelocateToLivePark）。
654:        // enteredAtTail：入口即为持久链尾的记录不由重入路径重开（BO-6 防御语义）。
655:        var enteredAtTail = run.TailReached;
656:        try
657:        {
658:            if(plan.ValidatePathCursor(run,bindNew:true))_runs.Update(run);
659:            await VerifyStopAuthorityAsync(run, ct).ConfigureAwait(false);
660:            // 顶层触发器：入口等待（不占槽位；已消费则跳过——恢复不重等，B3）
661:            if (!run.TriggerConsumed)
662:            {
663:                var fired = await AwaitFlowTriggersAsync(run, plan, control, ct).ConfigureAwait(false);
664:                if (control.PauseRequested) return Pause(run);
665:                if (!fired)
666:                {
667:                    run.State = WorkflowRunState.Cancelled;
668:                    run.Note = AppendNote(run.Note, "计划触发已过期或窗口未取得空闲，本次跳过；未发送、不收尾。");
669:                    _runs.Update(run);
670:                    return run;
671:                }
672:                run.TriggerConsumed = true;
673:                run.State = WorkflowRunState.Running;
674:                _runs.Update(run);
675:            }
676:
677:            if (plan.Document.Loop?.GetString("deadline") is { Length: > 0 } cutoffText && run.LoopDeadlineAt is null)
678:            {
679:                var start = run.TriggerTiming?.ScheduledAt ?? _opt.Clock();
680:                var at = TimeOnly.Parse(cutoffText);
681:                var cutoff = new DateTimeOffset(start.Date + at.ToTimeSpan(), start.Offset);
682:                if (cutoff <= start) cutoff = cutoff.AddDays(1);
683:                run.LoopDeadlineAt = cutoff; _runs.Update(run);
684:            }
685:            var occurrence = Relocate(run, plan);
686:            if (occurrence is not null && run.Cursor is null)
687:            {
688:                // 首个待执行节点即落盘游标（B4：跳过动作绑定出现身份对首节点同样成立）
689:                ApplyRelocation(run, occurrence);
690:                _runs.Update(run);
691:            }
692:            while (true)
693:            {
694:                if (plan.HasPaths) await Task.Yield(); // 纯判断循环也让出线程，控制操作可以到达。
695:                ct.ThrowIfCancellationRequested();
696:                await VerifyStopAuthorityAsync(run, ct).ConfigureAwait(false);
697:                if (control.PauseRequested) return Pause(run);
698:
699:                // 边界①：显式动作 + 修订对账（新修订按稳定身份重算后继；链尾亦对账，B1）
700:                (plan, occurrence) = ProcessBoundaryActions(run, plan, occurrence, control);
701:                if (occurrence is null)
702:                {
703:                    // [BO-9 / R34 F5 重要；第 1 轮会诊 IMPORTANT-1 修复] 真实链尾：线性推进
704:                    // （plan.Next）到不了本链的更晚义务——无循环定义时既不回绕到更高轮次停驻
705:                    // （如 A@loop2），也到不了 RecomputeSuccessor 已选中但尚未履行的 rescue
706:                    // （如 [A,P] + A@0 完成 + P@1/P@2 停驻 ⇒ rescue A@1）。按计划全序重建并重入
707:                    // 最早的未履行恢复义务，避免「零发送义务/未执行出现被静默吞」后假成功。
708:                    // 终止性：每次重入都驱动该出现一次（完成或被过滤 ⇒ 离开义务集合；再次停驻或
709:                    // unknown ⇒ 驱动立即返回），义务集合严格收缩；重入后若经暂停/取消/修订边界返回，
710:                    // 驱动本身结束，不构成自旋。入口即链尾（持久 TailReached）不由本路径重开。
711:                    if (!enteredAtTail && TryRelocateToOutstandingObligation(run, plan, out var obligation))
712:                    {
713:                        Log(run, $"链尾仍存未履行的恢复义务 {obligation!.NodeId}#{obligation.Occurrence}"
714:                                 + $"（轮次 {obligation.LoopIteration}）：按计划全序重入重驱，不按链尾放行。");
715:                        occurrence = obligation;
716:                        ApplyRelocation(run, occurrence);
717:                        _runs.Update(run);
718:                        continue;
719:                    }
720:                    break; // 链尾（TailReached 已落盘）
721:                }
722:
723:                // B3-③：提交终态已观察但结果未提交（仅遗留/手工记录可达；正常路径单次写已消除窗口）
724:                // ——按提交事实补记结果，绝不重跑该节点
725:                if (run.CurrentSubmission is { ObservedTerminal: { } observed } pendingSub
726:                    && pendingSub.NodeId == occurrence.NodeId
727:                    && pendingSub.Occurrence == occurrence.Occurrence
728:                    && pendingSub.LoopIteration == occurrence.LoopIteration)
729:                {
730:                    var mapped = MapTerminal(observed);
731:                    Log(run, $"提交 {pendingSub.Key} 终态已观察（{observed}）但结果未提交，按事实补记，不重跑。");
732:                    CommitOutcome(run, plan, occurrence, mapped.Result, mapped.Reason, rawTerminal: observed); // I2：ObservedTerminal 已是原始词
733:                    if (mapped.Result == "cancelled") throw new OperationCanceledException();
734:                    if (mapped.Result is "failed" or "rejected" && !_opt.ContinueOnNodeFailure) break;
735:                    occurrence = Relocate(run, plan);
736:                    continue;
737:                }
738:
739:                if (run.LoopDeadlineAt is { } cutoff && _opt.Clock() >= cutoff)
740:                {
741:                    SettleDeadlineWait(run, plan);
742:                    run.Note = AppendNote(run.Note, "循环绝对截止已到，不再启动后续节点。");
743:                    ApplyRelocation(run, null); _runs.Update(run); break;
744:                }
745:                if (plan.Document.Loop is { Mode: "scheduled" } calendar && (calendar.GetBool("skipAcrossDays") ?? true))
746:                {
747:                    if (run.LoopRoundEndsAt is null)
748:                    {
749:                        var now = _opt.Clock(); var at = TimeOnly.Parse(calendar.GetString("time")!);
750:                        var end = new DateTimeOffset(now.Date + at.ToTimeSpan(), now.Offset);
751:                        run.LoopRoundEndsAt = end <= now ? end.AddDays(1) : end; _runs.Update(run);
752:                    }
753:                    if (_opt.Clock() >= run.LoopRoundEndsAt && occurrence.LoopIteration == run.LastScheduledRoundWait)
754:                    {
755:                        var expiredRound = occurrence.LoopIteration;
756:                        do
757:                        {
758:                            CommitOutcome(run, plan, occurrence, "skippedFilter", "跨天跳过本轮剩余节点，不补跑");
759:                            occurrence = Relocate(run, plan);
760:                        } while (occurrence is not null && occurrence.LoopIteration == expiredRound);
761:                        run.LoopRoundEndsAt = null; _runs.Update(run); continue;
762:                    }
763:                }
764:                // B9：轮次起点等待统一在新一轮边界（成功/过滤跳过/失败续跑同路径；不占槽位）
765:                if (occurrence is { SequenceIndex: 0, LoopIteration: > 0 }
766:                    && occurrence.LoopIteration != run.LastScheduledRoundWait)
767:                {
768:                    if (!await AwaitLoopRoundStartAsync(run, plan, occurrence, control, ct).ConfigureAwait(false))
769:                    {
770:                        if (run.LoopDeadlineAt is null) flowFailure = true;
771:                        else { ApplyRelocation(run, null); _runs.Update(run); }
772:                        break;
773:                    }
774:                    if (control.PauseRequested) return Pause(run);
775:                    if (run.LoopDeadlineAt is { } deadline && _opt.Clock() >= deadline)
776:                    { ApplyRelocation(run, null); _runs.Update(run); break; }
777:                }
778:
779:                // [BO-8] 恢复点或修订重排可能落在已完成出现之前。停驻义务照常重驱，但任何已完成
780:                // 稳定出现都不得二次提交。逐步推进（每步一个出现）保留定义边界与轮次起点处理。
781:                if (HasCompletedOutcome(run, occurrence))
782:                {
783:                    Log(run, $"推进过滤已完成出现 {occurrence.NodeId}#{occurrence.Occurrence}"
784:                             + $"（轮次 {occurrence.LoopIteration}）：按稳定身份跳过，不二次提交。");
785:                    occurrence = plan.Next(occurrence);
786:                    ApplyRelocation(run, occurrence);
787:                    _runs.Update(run);
788:                    continue;
789:                }
790:
791:                var node = plan.NodeAt(occurrence);
792:                var scheduleResult = await AwaitNodeScheduleAsync(run, node, occurrence, control, ct).ConfigureAwait(false);
793:                if (control.PauseRequested) return Pause(run);
794:                if (!scheduleResult)
795:                {
796:                    CommitOutcome(run, plan, occurrence, "skippedFilter", "节点固定时刻或灵活窗口已错过");
797:                    occurrence = Relocate(run, plan);
798:                    continue;
799:                }
800:                if (node.Kind == "control.condition")
801:                {
802:                    bool answer;
803:                    try { answer = plan.EvaluatePathCondition(node, _opt.Clock(), run); }
804:                    catch (WorkflowObservationUnknownException ex)
805:                    {
806:                        run.State=WorkflowRunState.Unknown;run.Note=AppendNote(run.Note,ex.Message);
807:                        _runs.Update(run);return run;
808:                    }
809:                    CommitOutcome(run, plan, occurrence, answer ? "branchYes" : "branchNo", "条件在本次到达求值，所选去向与结果同写落盘");
810:                    occurrence = Relocate(run, plan); continue;
811:                }
812:                if (node.Kind == "control.end")
813:                {
814:                    CommitOutcome(run, plan, occurrence, "succeeded", "已到达结束流程节点");
815:                    occurrence = Relocate(run, plan); continue;
816:                }
817:                var gate = plan.EvaluateNode(occurrence, _opt.Clock(), _boundary.SingleNativeSupported);
818:                if (gate.Action == NodeGateAction.Skip)
819:                {
820:                    Log(run, $"节点 {occurrence.NodeId}#{occurrence.LoopIteration} 过滤跳过：{gate.Reason}");
821:                    CommitOutcome(run, plan, occurrence, "skippedFilter", gate.Reason);
822:                    occurrence = Relocate(run, plan);
823:                    continue;
824:                }
825:                if (gate.Action == NodeGateAction.Reject)
826:                {
827:                    Log(run, $"节点 {occurrence.NodeId}#{occurrence.LoopIteration} 响亮拒绝：{gate.Reason}");
828:                    CommitOutcome(run, plan, occurrence, "rejected", gate.Reason);
829:                    if (!_opt.ContinueOnNodeFailure) break;
830:                    occurrence = Relocate(run, plan);
831:                    continue;
832:                }
833:
834:                // 前置策略（D8 + R4.6 结构化结果：Proceed/Failed/Rejected/Cancelled/Unknown；
835:                // 前置段已建立叶子令牌，SkipCurrent 可取消在飞前置并经确认链对账）
836:                if (await ExecutePrerequisitesAsync(run, node, occurrence, control, ct).ConfigureAwait(false) is { } prereqOutcome)
837:                {
838:                    if (prereqOutcome.Result is "unknown" or "cancelUnconfirmed")
839:                    {
840:                        // B3/四轮阻断 5：结果不确定——先置状态再 CommitOutcome（单次原子落盘，游标不推进；不触发收尾、禁止自动重跑）
841:                        run.State = WorkflowRunState.Unknown;
842:                        run.Note = AppendNote(run.Note, "前置动作结果不确定，标 Unknown（不推进、不触发收尾、禁止自动重跑）。");
843:                        CommitOutcome(run, plan, occurrence, prereqOutcome.Result, prereqOutcome.Reason);
844:                        return run;
845:                    }
846:                    CommitOutcome(run, plan, occurrence, prereqOutcome.Result, prereqOutcome.Reason);
847:                    if (prereqOutcome.Result == "cancelled") throw new OperationCanceledException();
848:                    if (prereqOutcome.Result is "failed" or "rejected" && !_opt.ContinueOnNodeFailure) break;
849:                    occurrence = Relocate(run, plan); // skippedUser/skippedFilter/失败续跑：推进
850:                    continue;
851:                }
852:
853:                // 提交（意图先行 → 提交 → 终态；观察终态+结果+游标单次落盘，B2/B3）
854:                var outcome = await SubmitAndAwaitAsync(run, plan, node, occurrence, control).ConfigureAwait(false);
855:                if (outcome.Result is LocalWaitResultWord)
856:                {
857:                    // **[批次 14／D1] 本地持久等待＝确定零发送的停驻**：与 unknown/cancelUnconfirmed 同族——
858:                    // **游标不推进**（`ApplyRelocation(run, occurrence)` 留在当前出现）、**不终态化**运行、
859:                    // **不触发收尾**、**不标 Unknown**（等待不是「结果不确定」，标 Unknown 会错误要求按幂等键+job 对账，
860:                    // 而本笔从未进入发送面 ⇒ 无 job 可查 ⇒ 永久无法收敛）。
861:                    // **[批次 20／Wave3／C11=(a)] 停驻态显式化**：置 **LocalWaitParking**（D-E4=(a) 不复用
862:                    // Running/Waiting）——运行无活动驱动、等待项就绪后可显式重驱（ResumeAsync 接受本状态）；
863:                    // 重启恢复扫描将其收敛为 Interrupted（可恢复）——「无重驱句柄的永久 Running」形态消除
