1749:    private async Task WaitAsync(WorkflowRunRecord run, string kind, DateTimeOffset until, RunControl control, CancellationToken ct)
1750:    {
1751:        run.State = WorkflowRunState.Waiting;
1752:        run.Wait = new WaitStateRecord
1753:        {
1754:            Kind = kind,
1755:            NextTriggerAt = until,
1756:            TriggerOccurrenceId = $"{kind}:{until:yyyyMMddHHmm}",
1757:        };
1758:        _runs.Update(run);
1759:        Log(run, $"进入等待（{kind}）至 {until:yyyy-MM-dd HH:mm}（不持有执行锁、不提交等待作业）");
1760:        var delay = until - _opt.Clock();
1761:        if (_boundary.RequiresStopAuthority)
1762:        {
1763:            while (delay > TimeSpan.Zero)
1764:            {
1765:                await VerifyStopAuthorityAsync(run, ct).ConfigureAwait(false);
1766:                using var sliceCts = CancellationTokenSource.CreateLinkedTokenSource(ct);
1767:                var slice = _opt.DelayAsync(delay < TimeSpan.FromSeconds(2) ? delay : TimeSpan.FromSeconds(2), sliceCts.Token);
1768:                if (await Task.WhenAny(slice, control.PauseSignal.Task).ConfigureAwait(false) != slice)
1769:                {
1770:                    sliceCts.Cancel();
1771:                    try { await slice.ConfigureAwait(false); } catch (OperationCanceledException) { }
1772:                    return;
1773:                }
1774:                await slice.ConfigureAwait(false);
1775:                delay = until - _opt.Clock();
1776:            }
1777:            await VerifyStopAuthorityAsync(run, ct).ConfigureAwait(false);
1778:        }
1779:        else if (delay > TimeSpan.Zero)
1780:        {
1781:            // R4.8 一轮 I5：延时走独立链接令牌——暂停打断即取消遗留 delayTask（手动时钟夹具不悬挂、计时器不泄漏）
1782:            using var delayCts = CancellationTokenSource.CreateLinkedTokenSource(ct);
1783:            var delayTask = _opt.DelayAsync(delay, delayCts.Token);
1784:            if (await Task.WhenAny(delayTask, control.PauseSignal.Task).ConfigureAwait(false) != delayTask)
1785:            {
1786:                delayCts.Cancel();
1787:                try { await delayTask.ConfigureAwait(false); }
1788:                catch (OperationCanceledException) { /* 暂停打断的主动取消，按暂停语义返回 */ }
1789:                return; // 暂停打断：Wait 记录保留，恢复后按 NextTriggerAt 重排剩余
1790:            }
1791:            await delayTask.ConfigureAwait(false); // 传播 Stop 取消
1792:        }
1793:        run.Wait = null;
1794:        run.State = WorkflowRunState.Running;
1795:        _runs.Update(run);
1796:    }
