1841:    /// <summary>
1842:    /// 按稳定出现身份重算后继（B1：修订插入/删除/重排不错位）。
1843:    /// **[批次 20／Wave1 R5 重要-2]** 锚＝最后一条**完成**结果（排除 <see cref="LocalWaitResultWord"/>
1844:    /// 停驻标记——它零发送、未完成；**不得**按停驻节点算 Next 或按链尾放行）。
1845:    /// **裁决次序（与实现逐字对齐，R15 建议-4）**：①完成锚（含回溯）算出候选；②候选为 null 或
1846:    /// 存在可定位停驻出现时，**停驻义务优先**（不变量②：含前插保全）；③无停驻义务时取候选；
1847:    /// ④完成锚全不可定位且无停驻 ⇒ 链尾。**「无完成节点 ⇒ 取链首」仅在无停驻义务时成立。**
1848:    /// unknown/cancelUnconfirmed 同为非完成词，但其锚污染被 Unknown 禁恢复态挡住（恢复前必先对账并追加
1849:    /// 真实终态词），维持既有口径不动（本批不扩改既有恢复语义）。
1850:    /// **两条不变量（本批会诊逐轮收敛所得）**：
1851:    /// ①**不重跑已完成出现**——返回点本身先过滤完成结果（R12 重要-1）；驱动推进层对**整段推进**
1852:    /// 按稳定出现身份跳过已完成项（[BO-8] DriveAsync 完成过滤），真实链尾仍存活的停驻义务按计划
1853:    /// 全序重入（[BO-9] TryRelocateToLivePark），故本函数只需保证**返回点**未完成且不吞停驻义务；
1854:    /// ②**不吞停驻出现**——引擎自己立下的重驱义务（<see cref="LocalWaitResultWord"/>）：任何返回链尾
1855:    ///   （null/TailReached）的路径都必须先复核「计划中是否仍有可定位的停驻出现」，有则按它继续
1856:    ///   （R14 F2）；停驻出现之前若有**从未执行**的出现，则按更早者继续（R12 建议-1／R14 F1，
1857:    ///   且探针必须**与停驻同轮次**起步，不得锁死在第 0 轮）。
1858:    /// </summary>
1859:    internal WorkflowNodeOccurrence? RecomputeSuccessor(WorkflowRunRecord run, WorkflowPlan plan)
1860:    {
1861:        // 路径游标是已持久化的选中边；恢复/修订不能重新求条件或扫描未到达车道。
1862:        if (plan.HasPaths)
1863:        {
1864:            if (run.TailReached) return null;
1865:            if (run.Cursor is null) return plan.FirstOccurrence();
1866:            if (plan.TryLocate(run.Cursor.NodeId, run.Cursor.Occurrence, run.Cursor.LoopIteration, out var saved)) return saved with { PathLane = run.Cursor.PathLane };
1867:            throw new InvalidOperationException("路径中的待执行节点已被删除；保留原游标，不能猜测另一条路径。");
1868:        }
1869:        var completionOutcomes = run.NodeOutcomes.Where(o => o.Result != LocalWaitResultWord).ToList();
1870:        var parkedOutcomes = run.NodeOutcomes.Where(o => o.Result == LocalWaitResultWord).ToList();
1871:
1872:        // 锚回溯：最后完成节点在新修订中已删除时，回溯更早的仍可定位完成节点（R11 F-C）。
1873:        for (var i = completionOutcomes.Count - 1; i >= 0; i--)
1874:        {
1875:            var anchor = completionOutcomes[i];
1876:            if (!plan.TryLocate(anchor.NodeId, anchor.Occurrence, anchor.LoopIteration, out var anchorOcc)) continue;
1877:            if (i != completionOutcomes.Count - 1)
1878:            {
1879:                Log(run, $"最后完成身份 {completionOutcomes[^1].NodeId}#{completionOutcomes[^1].Occurrence} "
1880:                         + $"在新修订中已消失，回溯到更早可定位完成身份 {anchor.NodeId}#{anchor.Occurrence} 重算后继。");
1881:            }
1882:            var candidate = plan.Next(anchorOcc);
1883:            while (candidate is not null && HasCompletedOutcome(run, candidate))
1884:                candidate = plan.Next(candidate); // 不变量①：跳过已完成出现
1885:            // 锚可定位路径的返回可能落在**链尾**（candidate == null），也可能落在「锚之后仍有未完成工作」
1886:            // 的节点上——两者都不得吞掉停驻义务（不变量②）：
1887:            // ·链尾（R14 F2）：修订把停驻点重排到锚之前 ⇒ 纯向后走至 null ⇒ 假成功＋零发送节点被吞；
1888:            // ·非链尾（R15 重要-1）：修订把停驻点重排到锚之前**且锚之后还有未执行节点** ⇒ 返回那个
1889:            //   未执行节点、停驻点再也不被重驱 ⇒ 运行最终仍 Succeeded（同一可观察后果、另一条分支）。
1890:            // 故此处**无条件**复核停驻义务：有可定位停驻出现 ⇒ 以停驻义务为准（含其前插保全）；
1891:            // 无停驻 ⇒ 才用纯锚路径结果（保持 B1 修订语义不变）。
1892:            // [Wave1 R18 必改-1；BO-6/7-D1 修订] 下界：锚候选非 null ⇒ 候选本身；candidate 为 null
