97:public sealed partial class WorkflowRunner
98:{
99:    private async Task<bool> AwaitNodeScheduleAsync(WorkflowRunRecord run, WorkflowNode node,
100:        WorkflowNodeOccurrence occurrence, RunControl control, CancellationToken ct)
101:    {
102:        var schedule = node.Strategies.LastOrDefault(s => s.Kind == "schedule.time");
103:        if (schedule is null) return true;
104:        var key = $"schedule.time:{occurrence.NodeId}:{occurrence.LoopIteration}";
105:        var timing = WorkflowNodeSchedule.Bind(run, node, occurrence, _opt.Clock());
106:        _runs.Update(run);
107:        var at = timing.ScheduledAt;
108:        if (timing.Kind == "trigger.timeFixed" && _opt.Clock() >= at.AddMinutes(1))
109:        { run.Wait = null; run.State = WorkflowRunState.Running; _runs.Update(run); return false; }
110:        if (_opt.Clock() < at)
111:        {
112:            await WaitAsync(run, key, at, control, ct).ConfigureAwait(false);
113:            if (control.PauseRequested) return false;
114:        }
115:        if (timing.Kind == "trigger.timeFixed") return _opt.Clock() < at.AddMinutes(1);
116:        if (timing.Kind != "trigger.timeFlexible") return true;
117:        if (_opt.FlexibleFactsProvider is null) throw new InvalidOperationException("节点灵活窗口缺少实际空闲事实来源");
118:        while (_opt.Clock() < timing.WindowEndsAt)
119:        {
120:            await VerifyStopAuthorityAsync(run, ct).ConfigureAwait(false);
121:            if (TaskCenterMechanismPolicy.IsFlexiblyIdle(_opt.FlexibleFactsProvider(), out _)) return true;
122:            var next = _opt.Clock().AddSeconds(2);
123:            if (next > timing.WindowEndsAt) next = timing.WindowEndsAt!.Value;
124:            await WaitAsync(run, key, next, control, ct).ConfigureAwait(false);
125:            if (control.PauseRequested) return false;
126:        }
127:        return false;
128:    }
129:}
