408:        long? explicitIntentTimestamp = null, string? explicitIntentId = null, string? entryNodeId = null)
409:    {
410:        var intentTimestamp = explicitIntentTimestamp ?? System.Diagnostics.Stopwatch.GetTimestamp();
411:        var intentId = explicitIntentId ?? Guid.NewGuid().ToString("N");
412:        var snapshot = _workflows.LoadSnapshot(workflowId); // 隔离文件在此响亮抛出；文档+修订同源（B1）
413:        var plan = new WorkflowPlan(snapshot.Document);
414:        var preflight = plan.Preflight(_boundary.SingleNativeSupported, _prerequisites.SupportedKinds, _terminal.SupportedKinds,
415:            _boundary.SuppressConfigCompletionSupported); // R4.6 I1/B6：能力协商预检（含 suppress 能力）
416:        if (!preflight.Executable)
417:            throw new InvalidOperationException("流程预检未通过：" + string.Join("；", preflight.BlockingReasons));
