424:            throw new InvalidOperationException("运行登记冲突：" + run.RunId);
425:        try
426:        {
427:            return await DriveAsync(run, plan, control).ConfigureAwait(false);
428:        }
429:        finally
430:        {
431:            _controls.TryRemove(run.RunId, out _);
432:            control.RunCts.Dispose();
433:        }
434:    }
