630:            FreezeLegacyFixedTriggerPolicy(run, snapshot);
631:            run.WorkflowRevision = snapshot.Revision; // 恢复即对账到当前修订（节点边界语义）
632:            run.State = WorkflowRunState.Running;
633:            run.Note = AppendNote(run.Note, "显式恢复运行（游标身份重定位，不重放已完成节点）。");
