644:    private async Task<WorkflowRunRecord> DriveAsync(WorkflowRunRecord run, WorkflowPlan plan, RunControl control)
645:    {
646:        var ct = control.RunCts.Token;
647:        var flowFailure = false;
648:        // [BO-8 / R29 重要；继承缺陷] 推进段按**稳定出现身份**过滤已完成项：恢复点（显式恢复重算、
649:        // 修订热重载重算、或链尾重入的停驻）之后的线性推进不得二次提交已完成出现——修订重排把已
650:        // 完成节点挪到恢复点之后时，旧行为会重复触发外部副作用（不可撤销）。过滤只按
651:        // (NodeId, Occurrence, LoopIteration) 判定；停驻标记（LocalWaitResultWord）不算完成，
652:        // 停驻义务照常重驱。
653:        // [BO-9 / R34 F5 重要] 真实链尾仍存活的停驻义务按计划全序重入驱动（TryRelocateToLivePark）。
654:        // enteredAtTail：入口即为持久链尾的记录不由重入路径重开（BO-6 防御语义）。
655:        var enteredAtTail = run.TailReached;
656:        try
657:        {
658:            if(plan.ValidatePathCursor(run,bindNew:true))_runs.Update(run);
659:            await VerifyStopAuthorityAsync(run, ct).ConfigureAwait(false);
660:            // 顶层触发器：入口等待（不占槽位；已消费则跳过——恢复不重等，B3）
661:            if (!run.TriggerConsumed)
662:            {
663:                var fired = await AwaitFlowTriggersAsync(run, plan, control, ct).ConfigureAwait(false);
664:                if (control.PauseRequested) return Pause(run);
665:                if (!fired)
666:                {
667:                    run.State = WorkflowRunState.Cancelled;
668:                    run.Note = AppendNote(run.Note, "计划触发已过期或窗口未取得空闲，本次跳过；未发送、不收尾。");
669:                    _runs.Update(run);
670:                    return run;
671:                }
672:                run.TriggerConsumed = true;
673:                run.State = WorkflowRunState.Running;
674:                _runs.Update(run);
675:            }
676:
677:            if (plan.Document.Loop?.GetString("deadline") is { Length: > 0 } cutoffText && run.LoopDeadlineAt is null)
678:            {
679:                var start = run.TriggerTiming?.ScheduledAt ?? _opt.Clock();
680:                var at = TimeOnly.Parse(cutoffText);
681:                var cutoff = new DateTimeOffset(start.Date + at.ToTimeSpan(), start.Offset);
682:                if (cutoff <= start) cutoff = cutoff.AddDays(1);
683:                run.LoopDeadlineAt = cutoff; _runs.Update(run);
684:            }
685:            var occurrence = Relocate(run, plan);
686:            if (occurrence is not null && run.Cursor is null)
687:            {
688:                // 首个待执行节点即落盘游标（B4：跳过动作绑定出现身份对首节点同样成立）
689:                ApplyRelocation(run, occurrence);
690:                _runs.Update(run);
691:            }
692:            while (true)
693:            {
694:                if (plan.HasPaths) await Task.Yield(); // 纯判断循环也让出线程，控制操作可以到达。
695:                ct.ThrowIfCancellationRequested();
696:                await VerifyStopAuthorityAsync(run, ct).ConfigureAwait(false);
697:                if (control.PauseRequested) return Pause(run);
698:
699:                // 边界①：显式动作 + 修订对账（新修订按稳定身份重算后继；链尾亦对账，B1）
700:                (plan, occurrence) = ProcessBoundaryActions(run, plan, occurrence, control);
701:                if (occurrence is null)
702:                {
703:                    // [BO-9 / R34 F5 重要；第 1 轮会诊 IMPORTANT-1 修复] 真实链尾：线性推进
704:                    // （plan.Next）到不了本链的更晚义务——无循环定义时既不回绕到更高轮次停驻
705:                    // （如 A@loop2），也到不了 RecomputeSuccessor 已选中但尚未履行的 rescue
706:                    // （如 [A,P] + A@0 完成 + P@1/P@2 停驻 ⇒ rescue A@1）。按计划全序重建并重入
707:                    // 最早的未履行恢复义务，避免「零发送义务/未执行出现被静默吞」后假成功。
708:                    // 终止性：每次重入都驱动该出现一次（完成或被过滤 ⇒ 离开义务集合；再次停驻或
709:                    // unknown ⇒ 驱动立即返回），义务集合严格收缩；重入后若经暂停/取消/修订边界返回，
710:                    // 驱动本身结束，不构成自旋。入口即链尾（持久 TailReached）不由本路径重开。
711:                    if (!enteredAtTail && TryRelocateToOutstandingObligation(run, plan, out var obligation))
712:                    {
713:                        Log(run, $"链尾仍存未履行的恢复义务 {obligation!.NodeId}#{obligation.Occurrence}"
714:                                 + $"（轮次 {obligation.LoopIteration}）：按计划全序重入重驱，不按链尾放行。");
715:                        occurrence = obligation;
716:                        ApplyRelocation(run, occurrence);
717:                        _runs.Update(run);
718:                        continue;
