750:                        var end = new DateTimeOffset(now.Date + at.ToTimeSpan(), now.Offset);
751:                        run.LoopRoundEndsAt = end <= now ? end.AddDays(1) : end; _runs.Update(run);
752:                    }
753:                    if (_opt.Clock() >= run.LoopRoundEndsAt && occurrence.LoopIteration == run.LastScheduledRoundWait)
754:                    {
755:                        var expiredRound = occurrence.LoopIteration;
756:                        do
757:                        {
758:                            CommitOutcome(run, plan, occurrence, "skippedFilter", "跨天跳过本轮剩余节点，不补跑");
759:                            occurrence = Relocate(run, plan);
