763:                }
764:                // B9：轮次起点等待统一在新一轮边界（成功/过滤跳过/失败续跑同路径；不占槽位）
765:                if (occurrence is { SequenceIndex: 0, LoopIteration: > 0 }
766:                    && occurrence.LoopIteration != run.LastScheduledRoundWait)
767:                {
768:                    if (!await AwaitLoopRoundStartAsync(run, plan, occurrence, control, ct).ConfigureAwait(false))
769:                    {
770:                        if (run.LoopDeadlineAt is null) flowFailure = true;
771:                        else { ApplyRelocation(run, null); _runs.Update(run); }
772:                        break;
773:                    }
774:                    if (control.PauseRequested) return Pause(run);
775:                    if (run.LoopDeadlineAt is { } deadline && _opt.Clock() >= deadline)
776:                    { ApplyRelocation(run, null); _runs.Update(run); break; }
