894:
895:            await VerifyStopAuthorityAsync(run, ct).ConfigureAwait(false);
896:            // 流程边界：聚合判定只信 NodeOutcomes（B3：含恢复后的历史结果重建，失败不被成功覆盖）
897:            var unresolvedParkedOutcome = run.NodeOutcomes.Any(o => o.Result == LocalWaitResultWord
898:                && plan.TryLocate(o.NodeId, o.Occurrence, o.LoopIteration, out var parked)
899:                && !HasCompletedOutcome(run, parked));
900:            var hadBadOutcome = run.NodeOutcomes.Any(o =>
901:                o.Result is "failed" or "rejected" or "cancelled" or "cancelUnconfirmed" or "unknown"); // R4.6 B3
902:            if (hadBadOutcome || unresolvedParkedOutcome || flowFailure)
903:            {
904:                run.State = WorkflowRunState.Failed;
905:                run.Note = AppendNote(run.Note, flowFailure
