1343:        // 再纯观察确认；AwaitTerminalAsync 不再承担取消副作用（确认超时不重发取消，15s 预算即实际退出上界）
1344:        try
1345:        {
1346:            using var cancelBudget = CancellationTokenSource.CreateLinkedTokenSource(ct);
1347:            cancelBudget.CancelAfter(TimeSpan.FromSeconds(5));
1348:            await _boundary.RequestSubmissionCancelAsync(run, submission, cancelBudget.Token).ConfigureAwait(false);
1349:        }
1350:        catch (OperationCanceledException) when (ct.IsCancellationRequested) { throw; }
1351:        catch { /* best-effort：取消请求失败不阻断确认观察，终态以观察为准 */ }
1352:
1353:        using var timeout = CancellationTokenSource.CreateLinkedTokenSource(ct);
1354:        timeout.CancelAfter(_opt.SkipConfirmTimeout);
1355:        try
1356:        {
1357:            var terminal = await _boundary.AwaitSubmissionExitAsync(run, submission, timeout.Token).ConfigureAwait(false);
1358:            if (terminal.Uncertain || !terminal.ExecutionExitConfirmed)
1359:                return ("cancelUnconfirmed", $"跳过请求后远端终态/退出不可考（{Sanitize(terminal.Reason)}）", null);
1360:            submission.ExecutionExitConfirmed = terminal.ExecutionExitConfirmed;
1361:            submission.ExecutionExitDisposition = terminal.ExecutionExitDisposition;
1362:            submission.EffectState = terminal.Terminal;
1363:            return terminal.Terminal switch
1364:            {
1365:                "cancelled" => ("skippedUser", "显式跳过当前节点（远端取消已确认）", terminal.Terminal),
1366:                // I2：显式跳过意图与远端正常跳过竞态——如实记 skippedFilter（不计 skippedUser；两者均不阻断收尾，D15）
1367:                "skipped" => ("skippedFilter", "跳过请求到达时远端已正常跳过（来源保留，不计入显式跳过）", terminal.Terminal),
1368:                "succeeded" => ("succeeded", "跳过请求到达时节点已完成（留痕，不算跳过）", terminal.Terminal),
1369:                var t => ("failed", $"跳过请求后观察到意外终态 {Sanitize(t)}", terminal.Terminal),
1370:            };
1371:        }
1372:        catch (OperationCanceledException) when (!ct.IsCancellationRequested)
1373:        {
1374:            return ("cancelUnconfirmed", $"跳过请求后 {_opt.SkipConfirmTimeout.TotalSeconds:0}s 内远端终态未确认", null);
1375:        }
1376:    }
