1578:    /// <summary>顶层触发器等待（多触发器取最近；未知触发器响亮失败；暂停可打断）。</summary>
1579:    private async Task<bool> AwaitFlowTriggersAsync(WorkflowRunRecord run, WorkflowPlan plan, RunControl control, CancellationToken ct)
1580:    {
1581:        if (plan.Document.Triggers.Count == 0) return true;
1582:        var selected = run.TriggerTiming;
1583:        if (selected is null)
1584:        {
1585:            foreach (var trigger in plan.Document.Triggers)
1586:            {
1587:                var timing = WorkflowTriggerSchedule.Resolve(trigger, _opt.Clock(), out var reason);
1588:                if (timing is null)
1589:                {
1590:                    if (trigger.Kind != "trigger.time" && reason?.StartsWith("已过期", StringComparison.Ordinal) == true) continue;
1591:                    throw new InvalidOperationException("触发器不可用：" + reason);
1592:                }
1593:                if (selected is null || timing.ScheduledAt < selected.ScheduledAt) selected = timing;
1594:            }
1595:            if (selected is null) return false;
1596:            run.TriggerTiming = selected;
1597:            _runs.Update(run); // 先耐久保存原选定时刻/错过策略；恢复按同一策略处置。
1598:        }
1599:        while (true)
1600:        {
1601:            await VerifyStopAuthorityAsync(run, ct).ConfigureAwait(false);
1602:            if (selected.Kind == "trigger.timeFixed" && _opt.Clock() >= selected.ScheduledAt.AddMinutes(1))
1603:            {
1604:                if (selected.MissPolicy == "skip") return false;
1605:                if (selected.MissPolicy != "nextDay") throw new InvalidOperationException("原固定触发的错过策略缺失，不能猜测恢复");
1606:                var next = TaskCenterMechanismPolicy.ResolveMissedFire(selected.ScheduledAt, _opt.Clock(), MissPolicy.NextDay)!.Value;
1607:                selected = selected with { ScheduledAt = next, OriginalScheduledAt = selected.OriginalScheduledAt ?? selected.ScheduledAt };
1608:                run.TriggerTiming = selected;
1609:                _runs.Update(run); // 顺延先落盘，停止/重启仍沿同一原选择，不发送错过轮次。
1610:            }
1611:            await WaitAsync(run, selected.Kind, selected.ScheduledAt, control, ct).ConfigureAwait(false);
1612:            if (control.PauseRequested) return false;
1613:            if (selected.Kind != "trigger.timeFixed" || _opt.Clock() < selected.ScheduledAt.AddMinutes(1)) break;
1614:        }
1615:        if (selected.Kind == "trigger.timeFixed") return true;
1616:        if (selected.Kind != "trigger.timeFlexible") return true;
1617:        if (_opt.FlexibleFactsProvider is null) throw new InvalidOperationException("灵活窗口缺少实际空闲事实来源");
1618:        while (_opt.Clock() < selected.WindowEndsAt)
1619:        {
1620:            await VerifyStopAuthorityAsync(run, ct).ConfigureAwait(false);
1621:            if (TaskCenterMechanismPolicy.IsFlexiblyIdle(_opt.FlexibleFactsProvider(), out _)) return true;
1622:            var next = _opt.Clock().AddSeconds(2);
1623:            if (next > selected.WindowEndsAt) next = selected.WindowEndsAt!.Value;
1624:            await WaitAsync(run, selected.Kind, next, control, ct).ConfigureAwait(false);
1625:            if (control.PauseRequested) return false;
1626:        }
1627:        return false;
1628:    }
