1630:    private static void FreezeLegacyFixedTriggerPolicy(WorkflowRunRecord run, WorkflowSnapshot snapshot)
1631:    {
1632:        if (run.TriggerConsumed || run.TriggerTiming is not { Kind: "trigger.timeFixed", MissPolicy: null } timing) return;
1633:        if (run.WorkflowRevision != snapshot.Revision)
1634:            throw new InvalidOperationException("旧固定等待缺少原错过策略且流程定义已变化；保留原运行记录，不能猜测顺延或执行");
1635:        var policies = snapshot.Document.Triggers.Where(t => t.Kind == timing.Kind &&
1636:            TimeOnly.TryParse(t.GetString("time") ?? t.GetString("at"), out var time) && time.ToTimeSpan() == timing.ScheduledAt.TimeOfDay)
