1643:    private void SettleDeadlineWait(WorkflowRunRecord run, WorkflowPlan plan)
1644:    {
1645:        if (RunStore.HasUnresolvedExternalFact(run))
1646:            throw new InvalidOperationException("截止仍有未决外部事实，保留责任，不能以等待过期释放");
1647:        var deferred = run.CurrentSubmission is { Intent: SubmitIntentState.LocalWaitDeferred };
1648:        if (deferred && (run.LocalWaitDecision?.NoSendConfirmed != true || run.CurrentSubmission!.SendAttempted ||
1649:            run.CurrentSubmission.InFlight || !string.IsNullOrEmpty(run.CurrentSubmission.JobId)))
1650:            throw new InvalidOperationException("截止等待缺少确定零发送事实，不能清偿");
1651:        var binding = run.LocalWaitDecision?.Binding;
1652:        if (binding != null)
1653:        {
1654:            if (!deferred || binding.RunId != run.RunId || binding.WorkflowId != run.WorkflowId ||
1655:                binding.NodeId != run.CurrentSubmission!.NodeId || binding.Occurrence != run.CurrentSubmission.Occurrence ||
1656:                binding.LoopIteration != run.CurrentSubmission.LoopIteration || _localWaitQueue == null)
1657:                throw new InvalidOperationException("截止等待绑定不完整，队列与原记录保留");
1658:            if (_localWaitQueue.Cancel(binding, "循环绝对截止，本次零发送等待已过期", _opt.Clock()) == LocalWaitBindingCancelResult.PayloadMismatch)
1659:                throw new InvalidOperationException("截止等待项载荷已变化，未取消他方等待");
1660:        }
1661:        if (_localWaitQueue?.Load().Any(item => item.State != LocalWaitItemState.Cancelled &&
1662:            item.StableIdentity.StartsWith(run.RunId + "|", StringComparison.Ordinal)) == true)
1663:            throw new InvalidOperationException("截止仍有未核对的本次等待项，不能假称收口");
1664:        // Preserve old park markers; append an explicit deadline outcome for each still-live occurrence.
1665:        foreach (var park in run.NodeOutcomes.Where(o => o.Result == LocalWaitResultWord).ToArray())
1666:            if (plan.TryLocate(park.NodeId, park.Occurrence, park.LoopIteration, out var occurrence) && !HasCompletedOutcome(run, occurrence))
1667:                CommitOutcome(run, plan, occurrence, "skippedFilter", "循环绝对截止，零发送停驻不再重驱");
1668:        if (deferred) run.CurrentSubmission = null;
1669:        run.LocalWaitDecision = null;
1670:        _runs.Update(run);
1671:    }
