1722:    private async Task VerifyStopAuthorityAsync(WorkflowRunRecord run, CancellationToken ct)
1723:    {
1724:        if (!_boundary.RequiresStopAuthority) return;
1725:        if (_runs.Load(run.RunId) is { StopRequested: true })
1726:            throw new OperationCanceledException("运行已耐久停止，不允许恢复或推进", ct);
1727:        if (run.StopAuthority is not { } authority)
1728:            throw new StopAuthorityUnknownException("旧运行缺少停止基线，禁止自动刷新；需要只读对账或新显式运行。");
1729:        bool? current;
1730:        try
1731:        {
1732:            using var budget = CancellationTokenSource.CreateLinkedTokenSource(ct);
1733:            budget.CancelAfter(TimeSpan.FromSeconds(5));
1734:            current = _runs.IsStartupSourceRevoked(authority) ? false
1735:                : await _boundary.InspectStopAuthorityAsync(authority, budget.Token).ConfigureAwait(false);
1736:        }
