1798:    /// <summary>边界动作处理：修订对账（默认节点边界生效）+ 显式动作消费。</summary>
1799:    private (WorkflowPlan Plan, WorkflowNodeOccurrence? Occurrence) ProcessBoundaryActions(
1800:        WorkflowRunRecord run, WorkflowPlan plan, WorkflowNodeOccurrence? occurrence, RunControl control)
1801:    {
1802:        var reloadRequested = false;
1803:        while (control.Actions.TryDequeue(out var action))
1804:        {
1805:            switch (action)
1806:            {
1807:                case WorkflowRunAction.ReloadDefinition:
1808:                    reloadRequested = true;
1809:                    break;
1810:                case WorkflowRunAction.SkipCurrent:
1811:                    Log(run, "显式跳过请求已登记（绑定请求时出现身份；叶子建立即生效）。");
1812:                    break;
1813:                // Stop/Pause 经运行令牌/暂停标志生效，不在此消费
1814:            }
1815:        }
1816:
1817:        var snapshot = _workflows.LoadSnapshot(run.WorkflowId); // 文档+修订同源（B1）
1818:        if (!reloadRequested && snapshot.Revision == run.WorkflowRevision) return (plan, occurrence);
1819:
1820:        var newPlan = new WorkflowPlan(snapshot.Document);
1821:        var preflight = newPlan.Preflight(_boundary.SingleNativeSupported, _prerequisites.SupportedKinds, _terminal.SupportedKinds,
1822:            _boundary.SuppressConfigCompletionSupported); // R4.6 I1：重载入口同接能力协商预检
1823:        if (!preflight.Executable)
1824:        {
1825:            Log(run, "流程新修订预检未通过，沿用旧定义继续：" + string.Join("；", preflight.BlockingReasons));
1826:            return (plan, occurrence);
1827:        }
1828:
1829:        try{newPlan.ValidatePathCursor(run);}
1830:        catch(InvalidOperationException ex){Log(run,"新路径布局不能接续本次运行，沿用原定义："+ex.Message);return (plan,occurrence);}
1831:        // 新修订节点边界生效：从最后完成身份在新定义中重算后继（B1：插入/删除/重排不错位；
1832:        // occurrence 为 null 时即链尾对账——新修订追加的节点会被执行）
1833:        var relocated = RecomputeSuccessor(run, newPlan);
1834:        run.WorkflowRevision = snapshot.Revision;
1835:        ApplyRelocation(run, relocated);
1836:        _runs.Update(run);
1837:        Log(run, $"流程定义已重载（修订 {snapshot.Revision[..Math.Min(8, snapshot.Revision.Length)]}…），按稳定身份重算后继，节点边界生效。");
1838:        return (newPlan, relocated);
1839:    }
