97:                || s.SendPermit?.OriginalSendIdentity == sendIdentity) > 1) return false;
98:        var associations = run.RecoveryAssociations.Where(a => a.SubmissionKey == submission.Key
99:            || !string.IsNullOrEmpty(sendIdentity) && a.SubmissionIdentity == sendIdentity).ToList();
100:        if (associations.Count > 1 || associations.Any(a => a.SubmissionKey != submission.Key
101:            || a.SubmissionIdentity != sendIdentity)) return false;
102:        var related = run.NodeOutcomes.Where(o => o.SubmissionKey == submission.Key
103:            || !string.IsNullOrEmpty(sendIdentity) && o.AcceptedSendIdentity == sendIdentity).ToList();
104:        return related.Count <= 1 && related.All(o => o.SubmissionKey == submission.Key
105:            && (string.IsNullOrEmpty(o.AcceptedSendIdentity) || o.AcceptedSendIdentity == sendIdentity)
106:            && o.NodeId == submission.NodeId && o.Occurrence == submission.Occurrence
107:            && o.LoopIteration == submission.LoopIteration && o.Attempt == submission.Attempt
108:            && (!BgiJobTerminalPolling.IsTerminal(submission.ObservedTerminal)
109:                || !BgiJobTerminalPolling.IsTerminal(o.RawTerminal) || o.RawTerminal == submission.ObservedTerminal)
