222:                    ?? r.RecoveryAssociations.FirstOrDefault(a => a.SubmissionKey == s.Key)?.SubmissionIdentity ?? "")))
223:        && r.PrerequisiteActions.All(a => PrerequisiteSettled(r, a))
224:        && r.CompletionHistory.All(c => CompletionSettled(r, c))
225:        && r.NodeOutcomes.All(o => LocalBranchSettled(r, o) || o.Result is "succeeded" or "failed" or "rejected" or "skippedUser" or "skippedFilter" or "cancelled"
226:            || r.State == WorkflowRunState.Cancelled && r.StopRequested && o.Result is "unknown" or "cancelUnconfirmed"
227:                && Submissions(r).Any(s => s.NodeId == o.NodeId && s.Occurrence == o.Occurrence && s.LoopIteration == o.LoopIteration
228:                    && (o.Attempt is null || s.Attempt == o.Attempt) && (o.SubmissionKey is null || s.Key == o.SubmissionKey)
229:                    && (o.AcceptedSendIdentity is null || s.AcceptedSendIdentity == o.AcceptedSendIdentity)
230:                    && (o.RawTerminal is null || s.ObservedTerminal == o.RawTerminal
231:                        || o.RawTerminal == "result_unknown" && HistoricalObservation(r, s) is not null) && BodySettled(r, s))
232:            || o.Result == WorkflowRunner.LocalWaitResultWord && (HistoricalWaitSettled(r, o)
233:                || r.State == WorkflowRunState.Cancelled && r.StopRequested
234:                    && o.RawTerminal is null && o.AcceptedSendIdentity is null
235:                    && Submissions(r).Any(s => s.NodeId == o.NodeId && s.Occurrence == o.Occurrence && s.LoopIteration == o.LoopIteration
236:                        && s.Intent == SubmitIntentState.LocalWaitDeferred && !s.SendAttempted && string.IsNullOrEmpty(s.JobId))));
