255:    internal static string? NodeHash(WorkflowRunRecord r, string sendIdentity, bool requireSettled)
256:    {
257:        var resolved = ResolveSubmissionBySendIdentity(r, sendIdentity);
258:        if (resolved is null) return null;
259:        var s = resolved;
260:        if (!UniqueOriginalOutcomeSet(r, s, sendIdentity)) return null;
261:        var observation = HistoricalObservation(r, s);
262:        var association = observation ?? (string.IsNullOrEmpty(s.AcceptedSendIdentity)
263:            ? r.RecoveryAssociations.Single(a => a.SubmissionIdentity == sendIdentity && ValidRecoveryAssociation(r, a)) : null);
264:        var outcomes = association is { OutcomeIndex: >= 0 }
265:            ? new List<WorkflowNodeOutcome> { r.NodeOutcomes[association.OutcomeIndex] }
266:            : r.NodeOutcomes.Where(o => o.SubmissionKey == s.Key && o.AcceptedSendIdentity == sendIdentity).ToList();
267:        var prerequisites = r.PrerequisiteActions.Where(a => a.NodeId == s.NodeId && a.Occurrence == s.Occurrence
268:            && a.LoopIteration == s.LoopIteration && a.Attempt == s.Attempt).ToList();
269:        var stoppedAndSettled = r.State == WorkflowRunState.Cancelled && r.StopRequested && RunSettled(r);
270:        if (requireSettled && (!BodySettled(r, s) || !s.SendAttempted || string.IsNullOrEmpty(s.JobId)
271:            || (outcomes.Count != 1 && !(outcomes.Count == 0 && (stoppedAndSettled || observation is not null && r.StopRequested)))
272:            || prerequisites.Any(a => !PrerequisiteSettled(r, a)))) return null;
273:        if (requireSettled && outcomes.Any(o => o.NodeId != s.NodeId || o.Occurrence != s.Occurrence
274:            || o.LoopIteration != s.LoopIteration || o.Attempt != s.Attempt
275:            || observation is null && (o.RawTerminal != s.ObservedTerminal
276:                || o.Result is not ("succeeded" or "failed" or "rejected" or "skippedUser" or "skippedFilter" or "cancelled") && !stoppedAndSettled))) return null;
277:        return association is null
278:            ? Hash(new { r.RunId, r.WireRunId, r.StopAuthority, Submission = s, Outcomes = outcomes, Prerequisites = prerequisites })
279:            : Hash(new { r.RunId, r.WireRunId, r.StopAuthority, Submission = s, Outcomes = outcomes, Prerequisites = prerequisites, Association = association });
280:    }
