126:    private static bool ValidHistoricalExecution(WorkflowRunRecord run, WorkflowSubmission sub, RecoveryAssociationRecord association)
127:    {
128:        var job = association.ObservedExecution;
129:        var identity = new BgiJobTerminalPolling.FrozenIdentity(sub.Epoch, sub.Key, run.WireRunId,
130:            sub.NodeId, sub.LoopIteration, sub.Occurrence, sub.Attempt);
131:        return job is not null && run.StopRequested && association.EvidenceSource == "host:historical_original_exit"
132:            && identity.Complete && identity.Matches(job)
133:            && WorkflowStopAuthority.Epoch(job.Epoch) == sub.Epoch && job.JobId == sub.JobId
134:            && BgiWorkflowExecutionBoundary.OriginalRequestMatches(job, sub.OriginalRequestEvidence)
135:            && sub.SendPermit is { Version: 1, Consumed: true } permit
136:            && Guid.TryParseExact(permit.Nonce, "N", out _) && permit.OriginalSendIdentity == association.SubmissionIdentity
137:            && !string.IsNullOrEmpty(sub.Fingerprint) && !string.IsNullOrEmpty(sub.ExpiresAtUtc)
138:            && BgiJobTerminalPolling.IsTerminal(job.State) && job.ExecutionExitConfirmed
139:            && job.ExecutionExitDisposition is "execution_exited" or "never_started"
140:            && (!BgiJobTerminalPolling.IsTerminal(sub.ObservedTerminal) || sub.ObservedTerminal == job.State)
141:            && (!sub.ExecutionExitConfirmed || sub.ExecutionExitDisposition == job.ExecutionExitDisposition)
142:            && (sub.EffectState is null or "unknown" || sub.EffectState == job.State);
143:    }
