150:    internal static WorkflowSubmission? ResolveSubmissionBySendIdentity(WorkflowRunRecord r, string sendIdentity)
151:    {
152:        var direct = Submissions(r).Where(s => s.AcceptedSendIdentity == sendIdentity).ToList();
153:        if (direct.Count == 1) return direct[0];
154:        if (direct.Count > 1) return null;
155:        var links = r.RecoveryAssociations.Where(a => string.Equals(a.SubmissionIdentity, sendIdentity, StringComparison.Ordinal)
156:            && !string.IsNullOrEmpty(a.JobId) && !string.IsNullOrEmpty(a.EvidenceSource)
157:            && !string.IsNullOrEmpty(a.SubmissionKey)).ToList();
158:        if (links.Count != 1) return null;
159:        var byKey = Submissions(r).Where(s => string.Equals(s.Key, links[0].SubmissionKey, StringComparison.Ordinal)).ToList();
