164:    internal static bool ValidRecoveryAssociation(WorkflowRunRecord run, RecoveryAssociationRecord association)
165:    {
166:        var identity = association.SubmissionIdentity;
167:        var separator = identity.LastIndexOf(':');
168:        if (!identity.StartsWith("sub:", StringComparison.Ordinal) || separator <= 4
169:            || !int.TryParse(identity[(separator + 1)..], System.Globalization.NumberStyles.None,
170:                System.Globalization.CultureInfo.InvariantCulture, out var sequence)
171:            || sequence <= 0 || sequence != association.SendSeq
172:            || association.HistoryIndex < 0 || association.HistoryIndex >= run.SubmissionHistory.Count
173:            || string.IsNullOrWhiteSpace(association.EvidenceSource) || association.ObservedAtUtc == default)
174:            return false;
175:        var submission = run.SubmissionHistory[association.HistoryIndex];
176:        if (string.IsNullOrEmpty(submission.Key)
177:            || !string.IsNullOrEmpty(submission.AcceptedSendIdentity)
178:                && (association.ObservedExecution is null || submission.AcceptedSendIdentity != identity)
179:            || association.SubmissionKey != submission.Key || association.HistoryHash != Hash(submission)
180:            || string.IsNullOrEmpty(submission.JobId) || association.JobId != submission.JobId
181:            || string.IsNullOrEmpty(submission.Epoch) || association.Epoch != submission.Epoch
182:            || submission.WireRunId != run.WireRunId || !submission.SendAttempted
183:            || !UniqueOriginalOutcomeSet(run, submission, identity)) return false;
184:        var outcomes = run.NodeOutcomes.Select((outcome, index) => (outcome, index))
185:            .Where(item => item.outcome.SubmissionKey == submission.Key).ToList();
186:        if (association.ObservedExecution is not null && !ValidHistoricalExecution(run, submission, association)) return false;
187:        if (outcomes.Count == 0)
188:            return association.OutcomeIndex == -1 && association.OutcomeHash is null
189:                && (association.ObservedExecution is not null && run.StopRequested
190:                    || run.State == WorkflowRunState.Cancelled && run.StopRequested && OriginalBodySettled(run, submission));
191:        if (outcomes.Count != 1 || outcomes[0].index != association.OutcomeIndex) return false;
192:        var outcome = outcomes[0].outcome;
193:        return association.OutcomeHash == Hash(outcome)
194:            && (string.IsNullOrEmpty(outcome.AcceptedSendIdentity) || outcome.AcceptedSendIdentity == identity)
195:            && outcome.NodeId == submission.NodeId && outcome.Occurrence == submission.Occurrence
196:            && outcome.LoopIteration == submission.LoopIteration && outcome.Attempt == submission.Attempt
197:            && (association.ObservedExecution is { } observed
198:                ? (outcome.RawTerminal is null or "result_unknown" || outcome.RawTerminal == observed.State)
199:                    && (outcome.Result is "unknown" or "cancelUnconfirmed"
200:                        || outcome.Result == observed.State || outcome.Result == "skippedUser" && observed.State == "cancelled"
201:                        || outcome.Result == "skippedFilter" && observed.State == "skipped")
202:                : outcome.RawTerminal == submission.ObservedTerminal);
203:    }
204:    private static bool HistoricalWaitSettled(WorkflowRunRecord r, WorkflowNodeOutcome wait)
205:    {
206:        var index = r.NodeOutcomes.IndexOf(wait);
207:        return r.NodeOutcomes.Skip(index + 1).Any(o => o.NodeId == wait.NodeId && o.Occurrence == wait.Occurrence
208:            && o.LoopIteration == wait.LoopIteration && (o.RawTerminal is null
209:                ? o.Result is "skippedFilter" or "skippedUser"
210:                : o.Result is "succeeded" or "failed" or "rejected" or "skippedUser" or "skippedFilter" or "cancelled"
211:                    && Submissions(r).Any(s => s.Key == o.SubmissionKey && s.AcceptedSendIdentity == o.AcceptedSendIdentity
212:                        && s.NodeId == o.NodeId && s.Occurrence == o.Occurrence && s.LoopIteration == o.LoopIteration
213:                        && s.Attempt == o.Attempt && s.ObservedTerminal == o.RawTerminal && BodySettled(r, s))));
