238:    private static bool LocalBranchSettled(WorkflowRunRecord run, WorkflowNodeOutcome outcome) =>
239:        outcome.Result is "branchYes" or "branchNo"
240:        && !string.IsNullOrWhiteSpace(outcome.NodeId)
241:        && outcome.RawTerminal is null && outcome.SubmissionKey is null
242:        && outcome.AcceptedSendIdentity is null && outcome.Attempt is null
243:        && !Submissions(run).Any(s => s.NodeId == outcome.NodeId && s.Occurrence == outcome.Occurrence
244:            && s.LoopIteration == outcome.LoopIteration);
