246:    internal static string RunHash(WorkflowRunRecord r)
247:    {
248:        var copy = JsonSerializer.Deserialize<WorkflowRunRecord>(JsonSerializer.Serialize(r))!;
249:        copy.TerminalRelease = null; copy.RecordRevision = 0; copy.UpdatedAt = default; copy.Note = null;
250:        var facts = JsonSerializer.Serialize(copy);
251:        if (copy.RecoveryAssociations.Count == 0) facts = facts.Replace(",\"recoveryAssociations\":[]", "", StringComparison.Ordinal);
252:        return Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(facts)));
253:    }
