282:    internal static bool ValidRunSeal(WorkflowRunRecord r) => r.TerminalRelease is { Scope: "run" } seal
283:        && seal.RunId == r.RunId && seal.WireRunId == r.WireRunId
284:        && (seal.FactsHash == RunHash(r) || r.RecoveryAssociations.Count == 0 && seal.FactsHash == EmptyAssociationRunHash(r))
285:        && RunSettled(r);
