287:    private static string EmptyAssociationRunHash(WorkflowRunRecord run)
288:    {
289:        var copy = JsonSerializer.Deserialize<WorkflowRunRecord>(JsonSerializer.Serialize(run))!;
290:        copy.TerminalRelease = null; copy.RecordRevision = 0; copy.UpdatedAt = default; copy.Note = null;
291:        return Hash(copy);
292:    }
293:    internal static TerminalReleaseSeal? NodeSeal(WorkflowRunRecord r, OperationRecord op)
294:    {
295:        if (!op.ResourceRef.StartsWith("node:", StringComparison.Ordinal) || string.IsNullOrEmpty(op.SubmissionIdentity)) return null;
296:        var seals = r.NodeReleaseSeals.Where(s => s.SubmissionIdentity == op.SubmissionIdentity).ToList();
297:        if (seals.Count != 1) return null;
298:        var seal = seals[0];
299:        var sub = ResolveSubmissionBySendIdentity(r, op.SubmissionIdentity);
300:        if (sub is null) return null;
301:        return seal.Scope == "node" && seal.RunId == r.RunId && seal.WireRunId == r.WireRunId
302:            && seal.FactsHash == NodeHash(r, op.SubmissionIdentity, true)
303:            && op.SubmissionIdentity == $"sub:{op.RequestIdentity}:{op.LastSendSeq}"
304:            && op.WireSubmitKey == sub.Key && op.TargetEpoch == sub.Epoch && op.ResourceRef == "node:" + sub.NodeId
305:            && op.Candidate?.NodeId == sub.NodeId
306:            && op.Candidate?.Occurrence == sub.Occurrence && op.Candidate?.LoopIteration == sub.LoopIteration
307:            && op.Candidate?.Attempt == sub.Attempt ? seal : null;
308:    }
