318:            if (current is null || current.RunId != runId) return null;
319:            if (current.TerminalRelease is not null) return TerminalReleaseEvidence.ValidRunSeal(current) ? current.TerminalRelease : null;
320:            if (!TerminalReleaseEvidence.RunSettled(current)) return null;
321:            var seal = new TerminalReleaseSeal(Guid.NewGuid().ToString("N"), "run", current.RunId, current.WireRunId,
322:                current.RecordRevision + 1, TerminalReleaseEvidence.RunHash(current), null);
323:            current.TerminalRelease = seal;
324:            Persist(current, current.RecordRevision, authorizedSeal: seal);
325:            return seal;
