329:    internal TerminalReleaseSeal? TrySealTerminalNode(string runId, OperationRecord op)
330:    {
331:        lock (_gate)
332:        {
333:            var current = Load(runId);
334:            if (current is null || current.RunId != runId) return null;
335:            var existing = TerminalReleaseEvidence.NodeSeal(current, op);
336:            if (existing is not null) return existing;
337:            if (current.TerminalRelease is not null || string.IsNullOrEmpty(op.SubmissionIdentity)) return null;
338:            var hash = TerminalReleaseEvidence.NodeHash(current, op.SubmissionIdentity, true);
339:            if (hash is null) return null;
