349:    /// <summary>[G7-residual·本批] 对账取得合法证据后**追加**一条恢复关联（CAS 下写入＋读回验证）。
350:    /// 守卫约束：已落盘关联只增不删/不改；目标历史提交必须**确实缺身份**（有身份走关联＝歧义，拒绝）；
351:    /// 同一 SubmissionKey 已有关联＝幂等返回既有（冲突身份则拒绝）。绝不修改历史原件、不放宽守卫。</summary>
352:    internal RecoveryAssociationRecord? TryAppendRecoveryAssociation(string runId, RecoveryAssociationRecord association)
353:    {
354:        lock (_gate)
355:        {
356:            var current = Load(runId);
357:            if (current is null || current.RunId != runId) return null;
358:            association = JsonSerializer.Deserialize<RecoveryAssociationRecord>(JsonSerializer.Serialize(association))!;
359:            if (!TerminalReleaseEvidence.ValidRecoveryAssociation(current, association)) return null;
360:            if (string.IsNullOrEmpty(association.SubmissionKey) || string.IsNullOrEmpty(association.SubmissionIdentity)
361:                || string.IsNullOrEmpty(association.JobId) || string.IsNullOrEmpty(association.EvidenceSource)) return null;
362:            // 目标历史提交必须存在且确实缺身份（不得给已有身份的提交再造关联）。
363:            var targets = TerminalReleaseEvidence.Submissions(current)
364:                .Where(s => string.Equals(s.Key, association.SubmissionKey, StringComparison.Ordinal)).ToList();
365:            if (targets.Count != 1 || !string.IsNullOrEmpty(targets[0].AcceptedSendIdentity)
366:                && (association.ObservedExecution is null || targets[0].AcceptedSendIdentity != association.SubmissionIdentity)) return null;
367:            // 幂等/冲突：同 Key 已有关联——同身份同 jobId 幂等返回，否则冲突拒绝。
368:            var existing = current.RecoveryAssociations.Where(a => string.Equals(a.SubmissionKey, association.SubmissionKey, StringComparison.Ordinal)).ToList();
369:            if (existing.Count > 0)
370:            {
371:                if (existing.Count != 1) return null;
372:                var prior = existing[0];
373:                return TerminalReleaseEvidence.ValidRecoveryAssociation(current, prior)
374:                    && prior.HistoryIndex == association.HistoryIndex && prior.HistoryHash == association.HistoryHash
375:                    && prior.OutcomeIndex == association.OutcomeIndex && prior.OutcomeHash == association.OutcomeHash
376:                    && string.Equals(prior.SubmissionIdentity, association.SubmissionIdentity, StringComparison.Ordinal)
377:                    && prior.SendSeq == association.SendSeq
378:                    && string.Equals(prior.JobId, association.JobId, StringComparison.Ordinal)
379:                    && string.Equals(prior.Epoch, association.Epoch, StringComparison.Ordinal)
380:                    && TerminalReleaseEvidence.Hash(prior.ObservedExecution!) == TerminalReleaseEvidence.Hash(association.ObservedExecution!)
381:                    ? prior : null;
382:            }
383:            if (current.TerminalRelease is not null) return null;
384:            current.RecoveryAssociations.Add(association);
385:            Persist(current, current.RecordRevision, authorizedRecoveryAssociation: association);
386:            // 读回验证：关联必须已耐久落盘且可被关联分支定位。
387:            var readback = Load(runId);
388:            return readback is not null && TerminalReleaseEvidence.ValidRecoveryAssociation(readback, association)
389:                && readback.RecoveryAssociations.Count(a => JsonSerializer.Serialize(a) == JsonSerializer.Serialize(association)) == 1
390:                ? association : null;
391:        }
392:    }
