791:                var node = plan.NodeAt(occurrence);
792:                var scheduleResult = await AwaitNodeScheduleAsync(run, node, occurrence, control, ct).ConfigureAwait(false);
793:                if (control.PauseRequested) return Pause(run);
794:                if (!scheduleResult)
795:                {
796:                    CommitOutcome(run, plan, occurrence, "skippedFilter", "节点固定时刻或灵活窗口已错过");
797:                    occurrence = Relocate(run, plan);
798:                    continue;
