810:                    occurrence = Relocate(run, plan); continue;
811:                }
812:                if (node.Kind == "control.end")
813:                {
814:                    CommitOutcome(run, plan, occurrence, "succeeded", "已到达结束流程节点");
815:                    occurrence = Relocate(run, plan); continue;
816:                }
817:                var gate = plan.EvaluateNode(occurrence, _opt.Clock(), _boundary.SingleNativeSupported);
818:                if (gate.Action == NodeGateAction.Skip)
819:                {
820:                    Log(run, $"节点 {occurrence.NodeId}#{occurrence.LoopIteration} 过滤跳过：{gate.Reason}");
821:                    CommitOutcome(run, plan, occurrence, "skippedFilter", gate.Reason);
822:                    occurrence = Relocate(run, plan);
823:                    continue;
824:                }
825:                if (gate.Action == NodeGateAction.Reject)
826:                {
827:                    Log(run, $"节点 {occurrence.NodeId}#{occurrence.LoopIteration} 响亮拒绝：{gate.Reason}");
828:                    CommitOutcome(run, plan, occurrence, "rejected", gate.Reason);
829:                    if (!_opt.ContinueOnNodeFailure) break;
830:                    occurrence = Relocate(run, plan);
831:                    continue;
832:                }
