844:                        return run;
845:                    }
846:                    CommitOutcome(run, plan, occurrence, prereqOutcome.Result, prereqOutcome.Reason);
847:                    if (prereqOutcome.Result == "cancelled") throw new OperationCanceledException();
848:                    if (prereqOutcome.Result is "failed" or "rejected" && !_opt.ContinueOnNodeFailure) break;
849:                    occurrence = Relocate(run, plan); // skippedUser/skippedFilter/失败续跑：推进
850:                    continue;

851:                }
