581:    private static void SyncCollection<TVm, TModel>(ObservableCollection<TVm> target, IReadOnlyList<TModel> source,
582:        Func<TModel, string> keyOf, Func<TModel, TVm> create, Action<TVm, TModel> update)
583:        where TVm : class
584:    {
585:        // 按键对齐增量更新（避免闪烁；新增尾部追加，缺失移除）
586:        var sourceKeys = source.Select(keyOf).ToHashSet(StringComparer.Ordinal);
587:        for (var i = target.Count - 1; i >= 0; i--)
588:        {
589:            // TVm 需暴露 Key
590:            if (target[i] is not IKeyedVm keyed || !sourceKeys.Contains(keyed.Key))
591:                target.RemoveAt(i);
592:        }
593:        foreach (var model in source)
594:        {
595:            var key = keyOf(model);
596:            var existing = target.OfType<IKeyedVm>().FirstOrDefault(v => v.Key == key);
597:            if (existing is TVm vm) update(vm, model);
598:            else target.Add(create(model));
599:        }
600:        // 二轮（重要6）：按源顺序重排（新入项默认尾部追加，对齐源序——历史 UpdatedAt 倒序持续成立）
601:        for (var i = 0; i < source.Count; i++)
602:        {
603:            var key = keyOf(source[i]);
604:            var cur = -1;
605:            for (var j = 0; j < target.Count; j++)
606:            {
607:                if (target[j] is IKeyedVm k && k.Key == key) { cur = j; break; }
608:            }
609:            if (cur >= 0 && cur != i) target.Move(cur, i);
610:        }
611:    }
