MultiplayerHoeingAssistant/Services/TaskCenter/WorkflowMigrationConsumer.cs 71
1:using System.Text.Json;
2:using MultiplayerHoeingAssistant.Models;
3:
4:namespace MultiplayerHoeingAssistant.Services;
5:
6:internal static class WorkflowMigrationConsumer
7:{
8:    internal const string TransactionField = "nativeMigrationTransactionId";
9:
10:    internal static async Task<WorkflowSnapshot> PrepareAsync(WorkflowStore store, string workflowId,
11:        IResourceCatalogTransport transport)
12:    {
13:        var source = store.LoadSnapshot(workflowId);
14:        if (source.Document.Activation?.Status != "candidate-ready")
15:            throw new InvalidOperationException("只有candidate-ready候选可以正式激活");
16:        if (source.Document.Nodes.Count == 0 || WorkflowKindCatalog.FindUnsupportedKinds(source.Document).Count != 0)
17:            throw new InvalidOperationException("候选为空或有未支持机制，不能激活");
18:        var copy = JsonSerializer.Deserialize<WorkflowDocument>(JsonSerializer.Serialize(source.Document))!;
19:        foreach (var node in copy.Nodes)
20:        {
21:            var revision = await WorkflowResourceEditor.ReadRevisionAsync(node, transport);
22:            if (!string.Equals(revision, node.Ref?.Revision, StringComparison.OrdinalIgnoreCase))
23:                throw new InvalidOperationException($"资源「{node.Ref?.Config}」版本与迁移候选不一致；请先安装该候选的标准配置，原件保留");
24:            // R1使用小写SHA，BGI使用大写；只有同字节资源才归一化到权威读回值。
25:            node.Ref!.Revision = revision;
26:        }
27:        return new WorkflowSnapshot(copy, source.Revision);
28:    }
29:
30:    internal static string Activate(WorkflowStore store, string workflowId, WorkflowSnapshot prepared)
