11:{
12:    internal const string Operation = "ext.config.migrateStandard";
13:    private sealed record FileInput(string configName, string contentFile, string contentRevision, string sourceRevision);
14:    internal sealed record Plan(string InstallId, string SourceRoot, JsonObject SourceHashes, object[] Files, string RecordFile, bool HasWorkflowHistory);
15:    internal sealed record InstallationBinding(string InstallId, string UserRoot, string State);
16:    private sealed record PeerStatus(string State, string UserRoot);
17:
18:    internal static Plan? Find(string candidateRoot, WorkflowSnapshot snapshot, bool hasWorkflowHistory)
19:        => FindCore(candidateRoot, snapshot.Document.WorkflowId!, snapshot.Document.Activation?.Status,
20:            snapshot.Document.Nodes.Select(n => new WorkflowMigrationResourceReference(n.Kind,
21:                n.Ref?.Config, n.Ref?.ConfigKey, n.Ref?.Revision)).ToArray(), hasWorkflowHistory);
22:
23:    internal static Plan? FindRecovery(string candidateRoot, WorkflowMigrationRecoveryDescriptor recovery, bool hasWorkflowHistory)
24:        => FindCore(candidateRoot, recovery.WorkflowId, recovery.ActivationStatus, recovery.Resources, hasWorkflowHistory);
25:
26:    private static Plan? FindCore(string candidateRoot, string workflowId, string? activationStatus,
27:        IReadOnlyList<WorkflowMigrationResourceReference> resources, bool hasWorkflowHistory)
28:    {
29:        if (!Directory.Exists(candidateRoot)) return null; // Old manually imported candidates retain their original revision contract.
30:        if (MigrationSwitchTransaction.HasReparsePoint(candidateRoot)) throw new InvalidOperationException("迁移目录有链接");
31:        foreach (var scope in Directory.GetDirectories(candidateRoot))
32:        {
33:            if (MigrationSwitchTransaction.HasReparsePoint(scope)) throw new InvalidOperationException("迁移索引目录有链接");
34:            var path = Path.Combine(scope, "source-index.json");
35:            if (!File.Exists(path)) continue;
36:            if (MigrationSwitchTransaction.HasReparsePoint(path)) throw new InvalidOperationException("迁移索引有链接");
37:            var index = JsonNode.Parse(File.ReadAllBytes(path))!.AsObject();
38:            if (index["flowIds"] is not JsonObject ids || !ids.ContainsKey(workflowId)) continue;
39:            var candidate = Path.GetFullPath(index["candidateDirectory"]!.GetValue<string>());
40:            if (!candidate.StartsWith(Path.GetFullPath(scope) + Path.DirectorySeparatorChar, StringComparison.OrdinalIgnoreCase))
41:                throw new InvalidOperationException("迁移目录身份不一致");
42:            var outputs = index["outputs"]!.AsObject();
43:            LegacyMigrationCandidateService.VerifyOutputs(candidate, outputs);
44:            var manifest = JsonNode.Parse(File.ReadAllBytes(Path.Combine(candidate, "manifest.json")))!.AsObject();
45:            var files = new List<object>();
46:            foreach (var node in resources)
47:            {
48:                if (node.Kind != "resource.oneDragonConfig" || node.Config is not { Length: > 0 } name)
49:                    throw new InvalidOperationException("迁移候选含未映射资源，不能自动安装");
50:                var key = node.ConfigKey;
51:                var source = manifest["sources"]!.AsArray().OfType<JsonObject>().Single(s => s["configKey"]!.GetValue<string>() == key);
52:                var relative = Path.Combine("standard", "OneDragon", name + ".json");
53:                if (!MigrationSwitchTransaction.IsSafeRelativePath(relative.Replace('\\', '/')) || !outputs.ContainsKey(relative))
54:                    throw new InvalidOperationException("迁移标准文件映射缺失，不猜测名称");
55:                var bytes = File.ReadAllBytes(Path.Combine(candidate, relative));
56:                var revision = Convert.ToHexString(SHA256.HashData(bytes));
57:                if (!revision.Equals(node.Revision, StringComparison.OrdinalIgnoreCase))
58:                    throw new InvalidOperationException("迁移候选引用已变化，未安装");
59:                var sourceName = source["file"]!.GetValue<string>();
60:                if (!MigrationSwitchTransaction.IsSafeRelativePath(sourceName) || Path.GetFileName(sourceName) != sourceName)
61:                    throw new InvalidOperationException("旧配置来源身份非法");
62:                if (!files.OfType<FileInput>().Any(f => f.configName == name))
63:                    files.Add(new FileInput(name, Path.Combine(candidate, relative), revision, source["sha256"]!.GetValue<string>()));
64:            }
65:            var orderedFiles = files.OfType<FileInput>().OrderBy(f => f.configName, StringComparer.OrdinalIgnoreCase).Cast<object>().ToArray();
66:            var id = "std-" + Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(
67:                workflowId + "\n" + JsonSerializer.Serialize(orderedFiles))))[..32].ToLowerInvariant();
68:            return new(id, index["source"]!.GetValue<string>(), index["sourceHashes"]!.AsObject(), orderedFiles,
69:                Path.Combine(scope, "installation-bindings", id, "binding.json"), hasWorkflowHistory || activationStatus == "active");
70:        }
71:        return null;
72:    }
73:
74:    internal static async Task InstallAsync(Plan plan, IResourceCatalogTransport transport)
75:    {
76:        RequireCapability(transport);
77:        var binding = LoadBinding(plan);
78:        var status = await SendAsync(plan, "status", transport, binding?.UserRoot);
79:        if (binding == null && status.State is not ("absent" or "rolledBack"))
80:            throw new InvalidOperationException("BGI已有安装记录但原本机目标绑定缺失，原记录保留；不能猜测安装归属");
81:        if (binding != null && status.State == "absent")
82:            throw new InvalidOperationException("原目标安装记录缺失，不能猜测先前写入；原配置与本机绑定保留");
83:        if (status.State is "absent" or "rolledBack") VerifySource(plan);
84:        else if (status.State is not ("prepared" or "installed"))
85:            throw new InvalidOperationException("安装有未完成回退，请先恢复该迁移");
86:        binding ??= new(plan.InstallId, status.UserRoot, "prepared");
87:        SaveBinding(plan, binding); // Bind the peer before any request that can write native configurations.
88:        if ((await SendAsync(plan, "install", transport, binding.UserRoot)).State != "installed")
89:            throw new InvalidOperationException("标准配置安装未得到真实读回确认，流程未激活");
90:        SaveBinding(plan, binding with { State = "installed" });
91:    }
92:
93:    internal static async Task RollbackAsync(Plan plan, IResourceCatalogTransport transport)
94:    {
95:        var binding = await ValidateRollbackPeerAsync(plan, transport);
96:        if (binding == null) return;
97:        if ((await SendAsync(plan, "rollback", transport, binding.UserRoot)).State != "rolledBack")
98:            throw new InvalidOperationException("流程已回退，但BGI标准配置回退未确认；安装记录保留，请重新执行迁移回退");
99:        SaveBinding(plan, binding with { State = "rolledBack" });
100:    }
101:
102:    internal static async Task<InstallationBinding?> ValidateRollbackPeerAsync(Plan plan, IResourceCatalogTransport transport)
103:    {
104:        RequireCapability(transport);
105:        var binding = LoadBinding(plan);
106:        var status = await SendAsync(plan, "status", transport, binding?.UserRoot);
107:        if (binding == null && status.State == "absent" && !plan.HasWorkflowHistory) return null;
108:        if (binding == null || status.State == "absent")
109:            throw new InvalidOperationException("原安装绑定或BGI安装记录缺失，不能认定整体回退；原件与映射保留");
110:        return binding;
111:    }
112:
113:    private static void RequireCapability(IResourceCatalogTransport transport)
114:    {
115:        if (!transport.IsReady || !transport.HasCapability("config.standardMigration"))
116:            throw new InvalidOperationException("请连接支持标准迁移安装的本版BGI，未修改旧配置");
117:    }
118:
119:    private static async Task<PeerStatus> SendAsync(Plan plan, string action, IResourceCatalogTransport transport, string? expectedUserRoot = null)
120:    {
121:        var response = await transport.SendAsync(Operation, new { installId = plan.InstallId, action, expectedUserRoot,
122:            files = action == "install" ? plan.Files : null }, CancellationToken.None);
123:        if (response == null) throw new InvalidOperationException("BGI安装/回退未确认；保留映射与安装身份，在静止后重试或迁移回退");
124:        using var doc = JsonDocument.Parse(response);
125:        var root = doc.RootElement.GetProperty("userRoot").GetString();
126:        if (root == null || !Path.IsPathFullyQualified(root) || expectedUserRoot != null &&
127:            !Path.GetFullPath(root).Equals(Path.GetFullPath(expectedUserRoot), StringComparison.OrdinalIgnoreCase))
128:            throw new InvalidOperationException("当前BGI不是本次标准安装的原目标，未认定回退；请连接原安装位置后重试");
129:        return new(doc.RootElement.GetProperty("status").GetString() ?? throw new InvalidOperationException("安装状态未知"), Path.GetFullPath(root));
130:    }
131:
132:    private static InstallationBinding? LoadBinding(Plan plan)
133:    {
134:        if (MigrationSwitchTransaction.HasReparsePoint(plan.RecordFile)) throw new InvalidOperationException("本机安装绑定有链接");
135:        if (!File.Exists(plan.RecordFile))
136:        {
137:            if (Directory.Exists(Path.GetDirectoryName(plan.RecordFile)))
138:                throw new InvalidOperationException("原安装意图目录存在但绑定缺失，原件保留；不能猜测先前写入或重建目标");
139:            return null;
140:        }
141:        var binding = JsonSerializer.Deserialize<InstallationBinding>(File.ReadAllBytes(plan.RecordFile))
142:            ?? throw new InvalidOperationException("本机安装绑定损坏，原件保留");
143:        if (binding.InstallId != plan.InstallId || !Path.IsPathFullyQualified(binding.UserRoot) ||
144:            binding.State is not ("prepared" or "installed" or "rolledBack"))
145:            throw new InvalidOperationException("本机安装绑定身份不符，原件保留");
146:        return binding;
147:    }
148:
149:    private static void SaveBinding(Plan plan, InstallationBinding binding)
150:    {
151:        if (MigrationSwitchTransaction.HasReparsePoint(plan.RecordFile)) throw new InvalidOperationException("本机安装绑定有链接");
152:        Directory.CreateDirectory(Path.GetDirectoryName(plan.RecordFile)!);
153:        var temporary = plan.RecordFile + "." + Guid.NewGuid().ToString("N") + ".tmp";
154:        using (var file = new FileStream(temporary, FileMode.CreateNew, FileAccess.Write, FileShare.None))
155:        { file.Write(JsonSerializer.SerializeToUtf8Bytes(binding)); file.Flush(true); }
156:        File.Move(temporary, plan.RecordFile, File.Exists(plan.RecordFile));
157:    }
158:
159:    private static void VerifySource(Plan plan)
160:    {
161:        var root = Path.GetFullPath(plan.SourceRoot);
162:        if (MigrationSwitchTransaction.HasReparsePoint(root)) throw new InvalidOperationException("旧配置来源有链接");
163:        var configFiles = Directory.GetFiles(Path.Combine(root, "OneDragon"), "*.json");
164:        if (configFiles.Length != plan.SourceHashes.Count(x => Path.GetDirectoryName(x.Key)!.Equals(Path.Combine(root, "OneDragon"), StringComparison.OrdinalIgnoreCase)))
165:            throw new InvalidOperationException("旧配置文件集合已变化，未安装");
166:        foreach (var pair in plan.SourceHashes)
167:        {
168:            var path = Path.GetFullPath(pair.Key);
169:            if (!path.StartsWith(root + Path.DirectorySeparatorChar, StringComparison.OrdinalIgnoreCase) ||
170:                MigrationSwitchTransaction.HasReparsePoint(path) || !File.Exists(path) ||
171:                !Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(path))).Equals(pair.Value!.GetValue<string>(), StringComparison.OrdinalIgnoreCase))
172:                throw new InvalidOperationException("迁移准备后旧数据已变化，未安装；原候选与原件保留");
173:        }
174:    }
175:}

