288:public static class WorkflowWeekdayFilter
289:{
290:    private static readonly Dictionary<string, DayOfWeek> NameMap = new(StringComparer.Ordinal)
291:    {
292:        ["周一"] = DayOfWeek.Monday,
293:        ["周二"] = DayOfWeek.Tuesday,
294:        ["周三"] = DayOfWeek.Wednesday,
295:        ["周四"] = DayOfWeek.Thursday,
296:        ["周五"] = DayOfWeek.Friday,
297:        ["周六"] = DayOfWeek.Saturday,
