317:public static class WorkflowTriggerSchedule
318:{
319:    /// <summary>
320:    /// 下一次触发时刻（本机时间）。missPolicy=nextDay：当日已过则顺延明天。
321:    /// 未知 missPolicy / 时间形状非法 → null + reason（响亮不猜）。
322:    /// </summary>
323:    public static DateTimeOffset? NextFire(WorkflowTrigger trigger, DateTimeOffset now, out string? reason)
324:    {
325:        reason = null;
326:        if (trigger.Kind is not ("trigger.time" or "trigger.timeFixed" or "trigger.timeFlexible"))
327:        {
328:            reason = "未支持的触发器类型：" + trigger.Kind;
329:            return null;
330:        }
331:        if (trigger.Kind is "trigger.timeFixed" or "trigger.timeFlexible")
332:            return Resolve(trigger, now, out reason)?.ScheduledAt;
333:        var time = trigger.GetString("time");
334:        if (!TimeOnly.TryParse(time, out var at))
335:        {
336:            reason = "触发时间形状非法：" + (time ?? "null");
337:            return null;
338:        }
339:        var missPolicyRaw = trigger.GetString("missPolicy") ?? "nextDay";
340:        // 未知 missPolicy 响亮拒绝（不套用保守映射）
341:        if (!string.Equals(missPolicyRaw, "nextDay", StringComparison.Ordinal)
342:            && !string.Equals(missPolicyRaw, "skip", StringComparison.Ordinal))
343:        {
344:            reason = "未支持的 missPolicy：" + missPolicyRaw;
345:            return null;
346:        }
347:        var missPolicy = TaskCenterMechanismPolicy.ParseMissPolicy(missPolicyRaw);
348:        var todayAt = new DateTimeOffset(now.Year, now.Month, now.Day, at.Hour, at.Minute, 0, now.Offset);
349:        // R5.4 IP3：使用 MechanismPolicy.ResolveMissedFire（skip=放弃，nextDay=顺延次日）
350:        var resolved = TaskCenterMechanismPolicy.ResolveMissedFire(todayAt, now, missPolicy);
351:        if (resolved is null) reason = "已过期且 missPolicy=skip（放弃，不补跑）";
352:        return resolved;
353:    }
354:    /// <summary>固定到点或灵活启动窗口；旧time保留原nextDay缺省。</summary>
355:    public static WorkflowTriggerTiming? Resolve(WorkflowTrigger trigger, DateTimeOffset now, out string? reason)
356:    {
357:        reason = null;
358:        if (trigger.Kind == "trigger.time")
359:        {
360:            var at = NextFire(trigger, now, out reason);
361:            return at is null ? null : new(trigger.Kind, at.Value, null);
362:        }
363:        if (trigger.Kind is not ("trigger.timeFixed" or "trigger.timeFlexible"))
364:        { reason = "未支持的触发器：" + trigger.Kind; return null; }
365:        if (!TimeOnly.TryParse(trigger.GetString("time") ?? trigger.GetString("at"), out var start))
366:        { reason = "启动时间须为HH:mm"; return null; }
367:        var due = new DateTimeOffset(now.Date + start.ToTimeSpan(), now.Offset);
368:        var policy = trigger.GetString("missPolicy") ?? "skip";
369:        if (policy is not ("skip" or "nextDay"))
370:        { reason = "missPolicy须为skip或nextDay"; return null; }
371:        if (trigger.Kind == "trigger.timeFixed")
372:        {
373:            var fire = TaskCenterMechanismPolicy.ResolveMissedFire(due, now, TaskCenterMechanismPolicy.ParseMissPolicy(policy));
374:            if (fire is null) { reason = "已过期：固定型跳过本次，不补跑"; return null; }
375:            return new(trigger.Kind, fire.Value, null) { MissPolicy = policy, OriginalScheduledAt = fire.Value };
376:        }
377:        if (!TimeOnly.TryParse(trigger.GetString("until"), out var end) || end == start)
378:        { reason = "灵活型须设置不同于启动时间的窗口结束时间until（HH:mm）"; return null; }
379:        var until = new DateTimeOffset(due.Date + end.ToTimeSpan(), due.Offset);
380:        if (until <= due) until = until.AddDays(1);
381:        if (due > now && until.AddDays(-1) > now) { due = due.AddDays(-1); until = until.AddDays(-1); }
382:        if (now >= until)
383:        {
384:            if (policy == "skip") { reason = "已过期：灵活窗口已结束，不补跑"; return null; }
385:            due = due.AddDays(1); until = until.AddDays(1);
386:        }
387:        return new(trigger.Kind, due, until);
388:    }
389:}
