288:public static class WorkflowWeekdayFilter
289:{
290:    private static readonly Dictionary<string, DayOfWeek> NameMap = new(StringComparer.Ordinal)
291:    {
292:        ["周一"] = DayOfWeek.Monday,
293:        ["周二"] = DayOfWeek.Tuesday,
294:        ["周三"] = DayOfWeek.Wednesday,
295:        ["周四"] = DayOfWeek.Thursday,
296:        ["周五"] = DayOfWeek.Friday,
297:        ["周六"] = DayOfWeek.Saturday,
298:        ["周日"] = DayOfWeek.Sunday,
299:    };
300:
301:    public static bool Matches(WorkflowStrategy strategy, DateTimeOffset now)
302:    {
303:        var days = strategy.GetStringArray("days");
304:        if (days is null) return true; // 缺省字段才是不过滤；显式空数组保留旧不自动运行语义
305:        if (days.Count == 0) return false;
306:        var boundary = strategy.GetString("dayBoundary") ?? "localMidnight";
307:        // v1 仅本地午夜日界；其他日界未知 → 响亮不猜（按不命中处理并留痕）
308:        if (!string.Equals(boundary, "localMidnight", StringComparison.Ordinal)) return false;
309:        return days.Any(d => NameMap.TryGetValue(d, out var dow) && now.DayOfWeek == dow);
310:    }
311:}
