391:/// <summary>
392:/// 结构性循环时刻计算（C08/C09）：每轮开始/跨天截止重新定义，不复制旧 startTime 缺陷（R1 迁移注记）。
393:/// D9/B9 定案公式：轮次窗口 = [本地起点, 下一本地起点)，时区 = 本机（v1 不套游戏服 4 点/联机宽限）。
394:/// immediate：紧接上一轮。scheduled：起点未到 → 等今日起点；已错过今日起点 →
395:/// skipAcrossDays=true（默认，与 R1 样例一致）跳过本轮排下一起点（不补跑跨天轮次），
396:/// skipAcrossDays=false 在本轮窗口内立即补跑（返回 now）。
397:/// </summary>
398:public static class WorkflowLoopSchedule
399:{
400:    public static DateTimeOffset? NextRoundStart(WorkflowLoop loop, DateTimeOffset now, out string? reason, DateTimeOffset? absoluteDeadline = null)
401:    {
402:        reason = null;
403:        if (absoluteDeadline is { } cutoff && now >= cutoff)
404:        { reason = "本次运行的绝对截止已到，不再延到新一天"; return null; }
405:        switch (loop.Mode)
406:        {
407:            case "immediate":
408:                // C09 循环截止：deadline 过期后不再继续（截止后不会继续）
409:                var deadline = loop.GetString("deadline");
410:                if (absoluteDeadline is null && !string.IsNullOrEmpty(deadline) && TimeOnly.TryParse(deadline, out var deadlineAt))
411:                {
412:                    var todayDeadline = new DateTimeOffset(now.Year, now.Month, now.Day, deadlineAt.Hour, deadlineAt.Minute, 0, now.Offset);
413:                    if (now >= todayDeadline)
414:                    {
415:                        reason = "已过循环截止时间（deadline=" + deadline + "），不再继续";
416:                        return null;
417:                    }
418:                }
419:                return now;
420:            case "scheduled":
421:            {
422:                var time = loop.GetString("time");
423:                if (!TimeOnly.TryParse(time, out var at))
424:                {
425:                    reason = "循环时间形状非法：" + (time ?? "null");
426:                    return null;
427:                }
428:                var skipAcrossDays = loop.GetBool("skipAcrossDays") ?? true; // 默认跨天跳过（保守不补跑）
429:                var todayAt = new DateTimeOffset(now.Year, now.Month, now.Day, at.Hour, at.Minute, 0, now.Offset);
430:                // C09 循环截止：deadline 过期后不再继续（截止后不会继续）
431:                var schedDeadline = loop.GetString("deadline");
432:                if (absoluteDeadline is null && !string.IsNullOrEmpty(schedDeadline) && TimeOnly.TryParse(schedDeadline, out var schedDeadlineAt))
433:                {
434:                    var todayDeadline = new DateTimeOffset(now.Year, now.Month, now.Day, schedDeadlineAt.Hour, schedDeadlineAt.Minute, 0, now.Offset);
435:                    if (now >= todayDeadline)
436:                    {
437:                        reason = "已过循环截止时间（deadline=" + schedDeadline + "），不再继续";
438:                        return null;
439:                    }
440:                }
441:                if (todayAt > now) return todayAt; // 本轮起点未到：等今日起点
442:                return skipAcrossDays ? todayAt.AddDays(1) : now; // 已错过起点：跨天跳过 / 窗口内立即补跑
443:            }
444:            default:
445:                reason = "未支持的循环模式：" + loop.Mode;
446:                return null;
447:        }
448:    }
