14:    internal void InitializeSchedule()
15:    {
16:        if (Draft.ExtensionData?.TryGetValue("scheduleLanes", out var lanes) == true && lanes.ValueKind == JsonValueKind.Array)
17:            foreach (var lane in lanes.EnumerateArray().Skip(1))
18:                if (lane.ValueKind == JsonValueKind.String && lane.GetString() is { Length: > 0 } name) Lanes.Add(name);
19:        InitializeUndo();
20:    }
21:    public void AddLane()
22:    {
23:        RememberSchedule(); EnablePaths(); Lanes.Add("支线 " + Lanes.Count); StoreLanes();
24:    }
25:    public void RemoveLane(int index)
26:    {
27:        if (index <= 0 || index >= Lanes.Count) return;
28:        if(Nodes.Any(n=>n.LaneIndex<=index && n.LaneIndex+n.LaneSpan>index))
29:            throw new InvalidOperationException("这条车道仍有任务或被跨列节点覆盖，请先移走任务或调整覆盖，再删除车道。");
30:        RememberSchedule();_scheduleChanging=true;
31:        try
32:        {
33:            string Shift(string target)
34:            {
35:                var parts=target.Split(':');
36:                if(parts.Length>=2 && (parts[0] is "lane" or "time") && int.TryParse(parts[1],out var lane))
37:                {
38:                    if(lane==index)return "removed:"+target;
39:                    if(lane>index){parts[1]=(lane-1).ToString();return string.Join(':',parts);}
40:                }
41:                return target;
42:            }
43:            foreach(var node in Nodes)
44:            {
45:                if(node.LaneIndex>index)node.LaneIndex--;
46:                node.NextTarget=Shift(node.NextTarget);node.YesTarget=Shift(node.YesTarget);node.NoTarget=Shift(node.NoTarget);
47:            }
48:            Lanes.RemoveAt(index);StoreLanes();
49:        }
50:        finally{_scheduleChanging=false;}
51:    }
52:    private void StoreLanes()
53:    {
54:        Draft.ExtensionData ??= new();
55:        Draft.ExtensionData["scheduleLanes"] = JsonSerializer.SerializeToElement(Lanes);
56:    }
57:    public void ScheduleNode(NodeEditVm node, int? minute, int lane = 0, bool remember = true)
58:    {
59:        if (!Nodes.Contains(node)) return;
60:        if (remember) RememberSchedule();
61:        _scheduleChanging=true;
62:        try
63:        {
64:        node.ScheduleTimeText = minute is { } value ? $"{value / 60:00}:{value % 60:00}" : "";
65:        node.LaneIndex = node.Model.Kind=="control.end" ? 0 : Math.Clamp(lane, 0, Lanes.Count - 1);
66:        node.LaneSpan = Math.Min(node.LaneSpan,Lanes.Count-node.LaneIndex);
67:        // Execution order follows the schedule; the same stable node remains a single entry.
68:        if (minute is not null)
69:        {
70:            var ordered = Nodes.OrderBy(n => n.Model.Kind=="control.end" ? int.MaxValue : n.ScheduleMinute ?? int.MaxValue).ThenBy(n=>n.Model.Kind=="control.end").ToArray();
71:            for (var i = 0; i < ordered.Length; i++)
72:            { Nodes.Move(Nodes.IndexOf(ordered[i]), i); }
73:            Draft.Nodes.Clear(); Draft.Nodes.AddRange(Nodes.Select(n => n.Model)); Renumber();
74:        }
75:        SelectedNode = node;
76:        }finally{_scheduleChanging=false;}
77:    }
