81:        RememberSchedule(); AppendSourceIndex = index; AppendNodeCommand.Execute(null);
82:        var node = Nodes.LastOrDefault();
83:        if (node is not null) ScheduleNode(node, minute, lane, remember: false);
84:        return node;
