119:        if (ScheduleTimeText.Length > 0 && ScheduleMinute is null) throw new InvalidOperationException("节点时间须为HH:mm。");
120:        if (ScheduleTimeText.Length > 0 && ScheduleModeIndex == 2 && !TimeOnly.TryParseExact(ScheduleUntilText,"HH:mm",out _))
121:            throw new InvalidOperationException("灵活窗口结束时间须为HH:mm。");
122:        var existing = target.Strategies.LastOrDefault(s => s.Kind == "schedule.time");
123:        if (ScheduleTimeText.Length == 0) target.Strategies.RemoveAll(s => s.Kind == "schedule.time");
124:        else
125:        {
126:            if (existing is null) { existing = new WorkflowStrategy { Kind = "schedule.time" }; target.Strategies.Add(existing); }
127:            existing.Params ??= new();
128:            existing.Params["time"] = JsonSerializer.SerializeToElement(ScheduleTimeText);
129:            existing.Params["mode"] = JsonSerializer.SerializeToElement(ScheduleModeIndex switch { 1 => "fixed", 2 => "flexible", _ => "sequence" });
130:            existing.Params["until"] = JsonSerializer.SerializeToElement(ScheduleUntilText);
131:        }
132:        target.ExtensionData ??= new(); target.ExtensionData["scheduleLane"] = JsonSerializer.SerializeToElement(LaneIndex);
