172:                throw new InvalidOperationException("installation_original_invalid");
173:            if (file.ContentFile != null || file.ContentRevision != null || file.ContentBase64 == null ||
174:                !OneDragonConfigShapePreflight.InspectBytes(Convert.FromBase64String(file.ContentBase64)).IsLoadable)
175:                throw new InvalidOperationException("installation_output_invalid");
176:        }
