178:    private static void RequireOwnedState(string root, Entry file)
179:    {
180:        var target = Target(root, file.ConfigName);
181:        if (!File.Exists(target))
182:        {
183:            if (file.OriginalBase64 != null) throw new InvalidOperationException("configuration_missing");
184:            return;
185:        }
186:        var current = File.ReadAllBytes(target);
187:        if (!current.SequenceEqual(Convert.FromBase64String(file.ContentBase64!)) &&
188:            (file.OriginalBase64 == null || !current.SequenceEqual(Convert.FromBase64String(file.OriginalBase64))))
189:            throw new InvalidOperationException("configuration_changed");
190:    }
