10:{
11:    private const string Schema="mistletoe.scheduleList";
12:    public static void Export(WorkflowStore store,string destination)
13:    {
14:        var entries=store.List();
15:        if(entries.Any(e=>e.Status==WorkflowFileStatus.Quarantined))throw new InvalidOperationException("列表中存在隔离文件，请先处置；未导出不完整列表。");
16:        var target=Path.GetFullPath(destination);
17:        if(entries.Any(e=>target.StartsWith(Path.GetDirectoryName(Path.GetFullPath(e.FilePath))!+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase)))
18:            throw new InvalidOperationException("导出目标不能位于流程存储目录内");
19:        var flows=new JsonArray();
20:        foreach(var e in entries)
21:        {
22:            var snapshot=store.LoadSnapshot(e.WorkflowId);
23:            var json=JsonNode.Parse(JsonSerializer.Serialize(snapshot.Document))!;
24:            json.AsObject().Remove(WorkflowMigrationConsumer.TransactionField);
25:            StripAccounts(json);flows.Add(json);
26:        }
27:        var package=new JsonObject{["schema"]=Schema,["schemaVersion"]=1,["flows"]=flows};
28:        var temp=target+"."+Guid.NewGuid().ToString("N")+".tmp";
29:        try{File.WriteAllText(temp,package.ToJsonString(new(){WriteIndented=true}),new UTF8Encoding(false));File.Move(temp,target,overwrite:true);}
30:        finally{if(File.Exists(temp))File.Delete(temp);}
31:    }
32:    public static IReadOnlyList<string> Import(WorkflowStore store,string source)
33:    {
34:        var bytes=File.ReadAllBytes(source);var json=JsonNode.Parse(bytes) as JsonObject ?? throw new InvalidDataException("调度列表须为JSON对象");
35:        if(json["schema"]?.GetValue<string>()!=Schema || json["schemaVersion"]?.GetValue<int>()!=1 || json["flows"] is not JsonArray flows)
36:            throw new InvalidDataException("不支持的调度列表格式");
37:        var documents=new List<WorkflowDocument>();
38:        foreach(var item in flows)
39:        {
40:            if(item is not JsonObject o || o["schema"]?.GetValue<string>()!=WorkflowDocumentSchema.Name || o["schemaVersion"]?.GetValue<int>()!=WorkflowDocumentSchema.Version)
41:                throw new InvalidDataException("列表包含不支持的流程；尚未导入任何项目。");
42:            var doc=o.Deserialize<WorkflowDocument>() ?? throw new InvalidDataException("流程为空");
43:            if(string.IsNullOrWhiteSpace(doc.Name) || doc.Nodes is null || doc.Triggers is null || doc.Terminal is null || doc.Nodes.Any(n=>n is null || n.Strategies is null))
44:                throw new InvalidDataException("流程必要字段无效；尚未导入任何项目。");
45:            doc.WorkflowId=WorkflowStore.NewWorkflowId();
46:            doc.ExtensionData ??=new();doc.ExtensionData.Remove(WorkflowMigrationConsumer.TransactionField);
47:            doc.ExtensionData["importedSchedule"]=JsonSerializer.SerializeToElement(true);
48:            doc.Activation=new(){Status="candidate-ready"};documents.Add(doc);
49:        }
50:        // 先完整判型，再一次持有原存储锁写入新身份；无覆盖既有流程，不自动执行。
51:        return store.WithMigrationWindow(()=>
52:        {
53:            var imported=new List<string>();
54:            try{foreach(var doc in documents){store.Save(doc,null);imported.Add(doc.WorkflowId!);}}
55:            catch(Exception ex){throw new IOException($"列表导入写入失败；已保留 {imported.Count} 个只读候选，原流程未覆盖。请刷新查看后处置。",ex);}
56:            return (IReadOnlyList<string>)imported;
57:        });
58:    }
59:    private static void StripAccounts(JsonNode node)
60:    {
61:        if(node is JsonObject obj)
62:        {
63:            foreach(var key in obj.Select(p=>p.Key).ToArray())
64:                if(new[]{"uid","bindingCode","GenshinUid","AccountBindingCode","AccountBinding"}.Contains(key,StringComparer.OrdinalIgnoreCase))obj.Remove(key);
65:                else if(obj[key] is {} child)StripAccounts(child);
66:        }
67:        else if(node is JsonArray list)foreach(var child in list)if(child is not null)StripAccounts(child);
68:    }
