1:using System.Windows;
2:using System.Windows.Controls;
3:using System.Windows.Media;
4:using System.Text.Json;
5:using MultiplayerHoeingAssistant.Models;
6:using MultiplayerHoeingAssistant.Services;
7:using MultiplayerHoeingAssistant.ViewModels;
8:using MultiplayerHoeingAssistant.Views;
9:using Xunit;
10:
11:namespace MultiplayerHoeingAssistant.UnitTest.ServiceTests.TaskCenter;
12:
13:public class FormalFlowContextTests
14:{
15:    [Fact]
16:    public Task SavedDraft_CanSelectSameNameCandidate_InBothViews() => OnSta((host, vm, first, second) =>
17:    {
