10:internal interface ITerminalEffectObserver
11:{
12:    IDisposable? PinOriginalProcess(BgiEpoch epoch);
13:    TerminalEffectProof? Observe(PendingCompletionRecord record, IDisposable? pinnedProcess);
14:}
15:
16:internal sealed class WindowsTerminalEffectObserver : ITerminalEffectObserver
17:{
18:    private readonly string _root;
19:    internal WindowsTerminalEffectObserver(string? root = null) => _root = root ?? TerminalEffectJournal.Root;
20:    public IDisposable? PinOriginalProcess(BgiEpoch epoch)
21:    {
22:        Process? process = null;
23:        try
24:        {
25:            process = Process.GetProcessById(epoch.ProcessId);
26:            // Force an OS handle now; PID reuse/absence after send never constitutes positive observation.
27:            _ = process.Handle;
28:            if (process.HasExited || process.StartTime.ToUniversalTime().Ticks != epoch.StartTicksUtc)
29:            { process.Dispose(); return null; }
30:            return process;
31:        }
32:        catch { process?.Dispose(); return null; }
33:    }
34:
35:    public TerminalEffectProof? Observe(PendingCompletionRecord record, IDisposable? pinnedProcess)
36:    {
37:        try
38:        {
39:            var token = record.TerminalEffectToken;
40:            if (!TerminalEffectJournal.ValidToken(token)) return null;
41:            bool Matches(TerminalEffectProgress p) => TerminalEffectJournal.Matches(p, token!, record.Epoch,
42:                record.JobId, record.IdempotencyKey, record.WireRunId, record.Action, record.TerminalRequestFingerprint);
43:            bool ProofMatches(TerminalEffectProof p) => TerminalEffectJournal.ProofMatches(p, token!, record.Epoch,
44:                record.JobId, record.IdempotencyKey, record.WireRunId, record.Action, record.TerminalRequestFingerprint);
45:            var progress = TerminalEffectJournal.Read<TerminalEffectProgress>(_root, token!);
46:            if (progress is null || !Matches(progress)) return null;
47:            var saved = TerminalEffectJournal.Read<TerminalEffectProof>(_root, token!, true);
48:            if (saved is not null) return saved.Progress == progress && ProofMatches(saved) ? saved : null;
49:            TerminalEffectProof? proof = null;
50:            if (record.Action == "shutdown")
51:            {
52:                var ids = TerminalEffectJournal.ConfirmShutdown(progress, ReadSystemEvents(progress.StartedAtUtc));
53:                if (ids is not null) proof = new(progress, "windows_system_shutdown_and_boot", DateTimeOffset.UtcNow, null, ids);
54:            }
55:            else if (pinnedProcess is Process process && process.Id + ":" + process.StartTime.ToUniversalTime().Ticks == record.Epoch
56:                && process.HasExited && process.ExitCode == 0)
57:                proof = new(progress, "original_process_handle_exit", DateTimeOffset.UtcNow, process.ExitCode, []);
58:            if (proof is null || !ProofMatches(proof)) return null;
59:            TerminalEffectJournal.Write(_root, token!, proof, true);
60:            var readback = TerminalEffectJournal.Read<TerminalEffectProof>(_root, token!, true);
61:            return readback is not null && ProofMatches(readback) ? readback : null;
62:        }
63:        catch { return null; } // Missing, corrupt, access denied or ambiguous facts retain original responsibility.
64:    }
65:
66:    private static IReadOnlyList<TerminalSystemEvent> ReadSystemEvents(DateTimeOffset since)
67:    {
68:        var utc = since.UtcDateTime.ToString("O", System.Globalization.CultureInfo.InvariantCulture);
69:        var query = new EventLogQuery("System", PathType.LogName,
70:            $"*[System[(EventID=1074 or EventID=6006 or EventID=12 or EventID=41 or EventID=6008) and TimeCreated[@SystemTime >= '{utc}']]]");
71:        using var reader = new EventLogReader(query);
72:        var events = new List<TerminalSystemEvent>();
73:        while (reader.ReadEvent() is { } entry)
74:        {
75:            using (entry)
76:            {
77:                if (events.Count >= 512) throw new InvalidDataException("Shutdown observation log range exceeds supported window");
78:                var xml = XDocument.Parse(entry.ToXml()); XNamespace ns = "http://schemas.microsoft.com/win/2004/08/events/event";
79:                var comment = xml.Descendants(ns + "Data").FirstOrDefault(d => (string?)d.Attribute("Name") == "param6")?.Value;
80:                if (entry.TimeCreated is null || entry.RecordId is null) throw new InvalidDataException("System event identity missing");
81:                events.Add(new(entry.Id, entry.ProviderName ?? "", entry.RecordId.Value,
82:                    new DateTimeOffset(entry.TimeCreated.Value.ToUniversalTime()), comment));
83:            }
84:        }
85:        return events;
86:    }
87:}

