6718:    private string? EnsureCapacityForCreate(LogicalOwnerLeaseFile file, DateTimeOffset now)
6719:    {
6720:        file.Handoff ??= new LeaseHandoffSegment();
6721:        MigrateAndClean(file, now);
6722:        var ops = file.Handoff.Operations;
6723:        var active = ops.Count(o => o.Zone == OperationZone.Active);
6724:        var pendingTransfer = ops.Count(o => o.Zone == OperationZone.TerminalPendingTransfer);
6725:        var tombstones = ops.Count(o => o.Zone == OperationZone.Tombstone);
6726:        // 只有真实清理事务能够删除的墓碑才计入可清理额度。
6727:        var cleanable = GetArchivableTerminalOperations(file, now)
6728:            .OrderBy(o => o.UpdatedAtUtc).FirstOrDefault()?.UpdatedAtUtc;
6729:        if (active + pendingTransfer >= PrimarySlotLimit)
6730:            return CapacityReject(active, pendingTransfer, tombstones, cleanable);
6731:        if (tombstones >= TombstoneLimit && cleanable is null)
6732:            return CapacityReject(active, pendingTransfer, tombstones, cleanable);
6733:        return null;
6734:    }
