6737:        OperationRecord op, LeaseSegment previousOwner, string evidenceSource, string? runId, string? jobId,
6738:        DateTimeOffset acceptedAtUtc, string? submissionIdentity = null, int? sendSeq = null)
6739:    {
6740:        var receiptSubmissionIdentity = submissionIdentity ?? op.SubmissionIdentity;
6741:        var receiptSendSeq = sendSeq ?? op.LastSendSeq;
6742:        var entry = new ExternalStartLedgerEntry
6743:        {
6744:            SubmissionIdentity = receiptSubmissionIdentity,
6745:            SendSeq = receiptSendSeq,
6746:            CandidateId = op.CandidateId,
6747:            ResourceRef = op.ResourceRef ?? "",
6748:            ActionId = op.Candidate?.ActionId ?? ArbitrationOrdering.DeriveActionId(op.CandidateId),
6749:            TargetBgiEpoch = op.TargetEpoch,
6750:            AcceptedAtUtc = acceptedAtUtc,
6751:            EvidenceSource = evidenceSource,
6752:            State = LedgerEntryState.AcceptedPendingExecution,
6753:            RunId = runId,
6754:            JobId = jobId,
6755:            OperationType = op.OperationType,
6756:        };
6757:        string? failure;
6758:        try { failure = await _hooks.LateAcceptanceReceiptPersist(entry).ConfigureAwait(false); }
6759:        catch (Exception ex) { failure = "late_receipt_persist_exception:" + ex.GetType().Name; }
6760:        // A late sender has no authority to borrow the current owner's lease generation and mutate Operation.
6761:        // It only appends the exact send-round receipt; the current owner's recovery scan materializes any conflict.
6762:        return LocatedStop(op.RequestIdentity, op,
